import type { DebugPanelPlacement } from '../core/index.js';

export function resolveDebugPanelPlacement(
  explicitPlacement: DebugPanelPlacement | undefined,
  logicalFixtureCount: number,
): DebugPanelPlacement {
  return explicitPlacement
    ?? (logicalFixtureCount === 1 ? 'canvas-right' : 'bottom-panel');
}
