import { ComponentDefinition, applyInputDefaults } from './fixtureApiConsumer.js';
import type {
	DebugPanelActivation,
	DebugPanelDefinition,
	IDisposable,
	RenderContext,
	RenderHost,
	RenderResult,
	StyleDefinition,
} from './fixtureApi.js';
import type { ExceptionError, RenderEventType } from './ErrorInfo.js';
import { getCachedContentHeight, setCachedContentHeight, getCachedContentWidth, setCachedContentWidth } from '../lib/fixtureSizeCache.js';
import { ConsoleEventsStore } from './ConsoleEventsStore.js';
import {
	FixtureDebugRuntime,
	FixtureInputRuntime,
	type ActiveDebugPanelSession,
} from './FixtureInteractionRuntime.js';

/** Maximum time a fixture render may take before it is reported as failed. */
export const RENDER_TIMEOUT_MS = 3000;

function isPromise(value: unknown): value is Promise<void> {
	return !!value && typeof (value as Promise<void>).then === 'function';
}

function injectStyles(
	styles: readonly StyleDefinition[],
	targetDoc: Document | ShadowRoot,
): { injectedElements: HTMLElement[]; adoptedSheets: CSSStyleSheet[] } {
	const injectedElements: HTMLElement[] = [];
	const adoptedSheets: CSSStyleSheet[] = [];
	const appendTarget = targetDoc instanceof ShadowRoot ? targetDoc : targetDoc.head;
	for (const style of styles) {
		if (style.type === 'css') {
			const styleEl = document.createElement('style');
			styleEl.textContent = style.content;
			appendTarget.appendChild(styleEl);
			injectedElements.push(styleEl);
		} else if (style.type === 'url') {
			const linkEl = document.createElement('link');
			linkEl.rel = 'stylesheet';
			linkEl.href = style.href;
			appendTarget.appendChild(linkEl);
			injectedElements.push(linkEl);
		} else if (style.type === 'adopted') {
			targetDoc.adoptedStyleSheets = [...targetDoc.adoptedStyleSheets, style.sheet];
			adoptedSheets.push(style.sheet);
		}
	}
	return { injectedElements, adoptedSheets };
}

function removeStyles(
	injectedElements: HTMLElement[],
	adoptedSheets: CSSStyleSheet[],
	targetDoc: Document | ShadowRoot,
): void {
	for (const el of injectedElements) {
		el.remove();
	}
	for (const sheet of adoptedSheets) {
		targetDoc.adoptedStyleSheets = targetDoc.adoptedStyleSheets.filter(s => s !== sheet);
	}
}

export class ComponentRendering {
	readonly renderTarget: HTMLElement;
	readonly iframe: HTMLIFrameElement | null = null;
	private readonly _abortController = new AbortController();
	private _resolvedResult: RenderResult | { error: ExceptionError } | undefined;
	private _injectedElements: HTMLElement[] = [];
	private _adoptedSheets: CSSStyleSheet[] = [];
	private _styleTarget: Document | ShadowRoot = document;
	private readonly _disposables: IDisposable[] = [];
	private readonly _rendered: Promise<RenderResult | undefined>;
	private readonly _inputRuntime: FixtureInputRuntime;
	private readonly _debugRuntime = new FixtureDebugRuntime();
	private readonly _iframeActiveSessions = new Set<ActiveDebugPanelSession>();
	private readonly _iframePanelStateHandlers = new Map<string, (state: unknown) => void>();
	private _iframeHasOutput = false;
	private _iframeOutputEditable = false;
	private _nextIframePanelSessionId = 0;
	private _currentInput: unknown;

	constructor(
		host: HTMLElement,
		readonly component: ComponentDefinition,
		private readonly _renderHost: RenderHost = { kind: 'headless', interactive: false },
		private readonly _input?: unknown,
	) {
		const isolation = component.isolation;
		const effectiveInput = applyInputDefaults(component.inputSchema, this._input);
		this._currentInput = effectiveInput;
		this._inputRuntime = new FixtureInputRuntime(effectiveInput);

		if (isolation === 'shadow-dom') {
			const shadowRoot = host.attachShadow({ mode: 'open' });
			this._styleTarget = shadowRoot;
			if (component.styles) {
				const { injectedElements, adoptedSheets } = injectStyles(component.styles, shadowRoot);
				this._injectedElements = injectedElements;
				this._adoptedSheets = adoptedSheets;
			}
			this.renderTarget = document.createElement('div');
			shadowRoot.appendChild(this.renderTarget);
		} else if (isolation === 'iframe') {
			const iframe = document.createElement('iframe');
			iframe.style.border = 'none';
			iframe.style.display = 'block';
			const isComponentMode = component.displayMode.type === 'component';
			if (isComponentMode) {
				iframe.style.width = (getCachedContentWidth(component.id) ?? 0) + 'px';
			} else {
				iframe.style.width = '100%';
			}
			iframe.style.height = (getCachedContentHeight(component.id) ?? 0) + 'px';

			const url = new URL(location.pathname, location.origin);
			url.searchParams.set('mode', 'embedded');
			url.searchParams.set('fixture', component.id);
			url.searchParams.set('file', component.sourceFile);
			iframe.src = url.toString();
			host.appendChild(iframe);
			this.iframe = iframe;

			let resolveRendered: ((result: RenderResult | undefined) => void) | undefined;
			let rejectRendered: ((error: ExceptionError) => void) | undefined;
			const onMessage = (e: MessageEvent) => {
				if (e.source !== iframe.contentWindow) return;
				if (e.data?.type === 'component-explorer:resize') {
					const height = e.data.height;
					const width = e.data.width;
					iframe.style.height = height + 'px';
					setCachedContentHeight(component.id, height);
					if (isComponentMode && width) {
						iframe.style.width = width + 'px';
						setCachedContentWidth(component.id, width);
					}
				} else if (e.data?.type === 'component-explorer:error') {
					const error = e.data.error as ExceptionError;
					this._resolvedResult = { error };
					rejectRendered?.(error);
					rejectRendered = undefined;
				} else if (e.data?.type === 'component-explorer:console') {
					// Forward iframe console events to the global store
					ConsoleEventsStore.getInstance().addEvent(
						e.data.eventType as RenderEventType,
						e.data.message,
						e.data.stack
					);
				} else if (e.data?.type === 'component-explorer:ready') {
					this._iframeHasOutput = e.data.hasOutput === true;
					this._iframeOutputEditable = e.data.outputEditable === true;
					resolveRendered?.(undefined);
					resolveRendered = undefined;
					rejectRendered = undefined;
				} else if (e.data?.type === 'component-explorer:embedded-loaded') {
					iframe.contentWindow?.postMessage({
						type: 'component-explorer:embedded-init',
						input: this._currentInput,
						host: this._renderHost,
					}, '*');
				} else if (e.data?.type === 'component-explorer:debug-panel-state') {
					const sessionId = typeof e.data.sessionId === 'string' ? e.data.sessionId : '';
					this._iframePanelStateHandlers.get(sessionId)?.(e.data.state);
				}
			};
			window.addEventListener('message', onMessage);
			this._abortController.signal.addEventListener('abort', () => {
				window.removeEventListener('message', onMessage);
			});

			this.renderTarget = iframe;
			this._rendered = new Promise<RenderResult | undefined>((resolve, reject) => {
				resolveRendered = resolve;
				rejectRendered = reject;
			});
			return;
		} else {
			if (component.styles) {
				const { injectedElements, adoptedSheets } = injectStyles(component.styles, document);
				this._injectedElements = injectedElements;
				this._adoptedSheets = adoptedSheets;
			}
			this.renderTarget = document.createElement('div');
			host.appendChild(this.renderTarget);
		}

		let rawResult: RenderResult | void | Promise<RenderResult | void>;
		try {
			const context = {
				fixtureId: component.id,
				signal: this._abortController.signal,
				addDisposable: <T extends IDisposable>(d: T): T => { this._disposables.push(d); return d; },
				watchInput: (key: string, listener: (value: unknown, input: unknown) => void): IDisposable => {
					const disposable = this._inputRuntime.watch(key, listener);
					this._disposables.push(disposable);
					return disposable;
				},
				debug: {
					connect: <TState, TAction>(
						panel: DebugPanelDefinition<TState, TAction>,
						activate: DebugPanelActivation<TState, TAction>,
					): IDisposable => this._connectDebugPanel(panel, activate),
				},
				host: this._renderHost,
				input: effectiveInput,
			};
			rawResult = component.render(this.renderTarget, context as RenderContext);
		} catch (err) {
			const error: ExceptionError = {
				message: err instanceof Error ? err.message : String(err),
				stack: err instanceof Error ? err.stack : undefined,
			};
			this._resolvedResult = { error };
			this._rendered = Promise.reject(error);
			return;
		}

		if (rawResult instanceof Promise) {
			this._rendered = rawResult.then((resolved) => {
				if (this._abortController.signal.aborted) {
					try {
						const r = resolved?.dispose?.();
						if (isPromise(r)) {
							r.catch(() => { /* aborted; swallow */ });
						}
					} catch { /* aborted; swallow */ }
					return undefined;
				}
				this._resolvedResult = resolved ?? undefined;
				this._debugRuntime.setOutput(resolved?.output);
				return this._resolvedResult as RenderResult | undefined;
			}).catch((err) => {
				const error: ExceptionError = {
					message: err instanceof Error ? err.message : String(err),
					stack: err instanceof Error ? err.stack : undefined,
				};
				this._resolvedResult = { error };
				throw error;
			});
		} else {
			this._resolvedResult = (rawResult ?? undefined) as RenderResult | undefined;
			this._debugRuntime.setOutput(this._resolvedResult?.output);
			this._rendered = Promise.resolve(this._resolvedResult as RenderResult | undefined);
		}
	}

	updateInput(input: unknown): boolean {
		const effectiveInput = applyInputDefaults(this.component.inputSchema, input);
		this._currentInput = effectiveInput;
		if (this.iframe) {
			this.iframe.contentWindow?.postMessage({
				type: 'component-explorer:embedded-input',
				input: effectiveInput,
			}, '*');
			return true;
		}
		return this._inputRuntime.update(effectiveInput);
	}

	get hasOutput(): boolean {
		return this.iframe ? this._iframeHasOutput : this._debugRuntime.hasOutput;
	}

	get outputEditable(): boolean {
		return this.iframe ? this._iframeOutputEditable : this._debugRuntime.outputEditable;
	}

	getOutputSnapshot(): unknown {
		if (this.iframe) {
			throw new Error('Iframe output snapshots are available through an activated Output panel');
		}
		return this._debugRuntime.getOutputSnapshot();
	}

	activateDebugPanel(
		panelId: string,
		publish: (state: unknown) => void,
	): ActiveDebugPanelSession {
		if (!this.iframe) {
			return this._debugRuntime.activate(panelId, publish);
		}

		const sessionId = `${this.component.id}:${this._nextIframePanelSessionId++}`;
		this._iframePanelStateHandlers.set(sessionId, publish);
		this.iframe.contentWindow?.postMessage({
			type: 'component-explorer:debug-panel-activate',
			sessionId,
			panelId,
		}, '*');

		let disposed = false;
		const session: ActiveDebugPanelSession = {
			sendAction: (action) => {
				if (disposed) return;
				this.iframe?.contentWindow?.postMessage({
					type: 'component-explorer:debug-panel-action',
					sessionId,
					action,
				}, '*');
			},
			dispose: () => {
				if (disposed) return;
				disposed = true;
				this._iframeActiveSessions.delete(session);
				this._iframePanelStateHandlers.delete(sessionId);
				this.iframe?.contentWindow?.postMessage({
					type: 'component-explorer:debug-panel-deactivate',
					sessionId,
				}, '*');
			},
		};
		this._iframeActiveSessions.add(session);
		return session;
	}

	private _connectDebugPanel<TState, TAction>(
		panel: DebugPanelDefinition<TState, TAction>,
		activate: DebugPanelActivation<TState, TAction>,
	): IDisposable {
		if (!this.component.debugPanels.some(candidate => candidate.id === panel.id)) {
			throw new Error(`Debug panel "${panel.id}" is not declared by fixture "${this.component.id}"`);
		}
		const disposable = this._debugRuntime.connect(
			panel.id,
			activate as DebugPanelActivation<unknown, unknown>,
		);
		this._disposables.push(disposable);
		return disposable;
	}

	async waitForRendering(): Promise<RenderResult | undefined> {
		const timeoutPromise = new Promise<never>((_, reject) => {
			const id = setTimeout(() => {
				reject(new Error(`Fixture timed out after ${RENDER_TIMEOUT_MS}ms`));
			}, RENDER_TIMEOUT_MS);
			this._abortController.signal.addEventListener('abort', () => clearTimeout(id));
		});
		try {
			const result = await Promise.race([this._rendered, timeoutPromise]);
			await Promise.race([result?.ready ?? Promise.resolve(), timeoutPromise]);
			return result;
		} catch (err) {
			if (this._renderHost.kind === 'embedded') {
				console.error(err instanceof Error ? err.message : String(err));
			}
			throw err;
		}
	}

	dispose(): Promise<readonly ExceptionError[]> {
		this._abortController.abort();
		for (const session of [...this._iframeActiveSessions]) {
			session.dispose();
		}
		this._debugRuntime.dispose();
		const errors: ExceptionError[] = [];
		const captureError = (err: unknown): void => {
			errors.push({
				message: err instanceof Error ? err.message : String(err),
				stack: err instanceof Error ? err.stack : undefined,
			});
		};

		const promises: Promise<void>[] = [];
		const runDispose = (fn: () => void | Promise<void>): void => {
			try {
				const r = fn();
				if (isPromise(r)) {
					promises.push(r.catch(captureError));
				}
			} catch (err) {
				captureError(err);
			}
		};

		if (this._resolvedResult && !('error' in this._resolvedResult)) {
			const fixtureDispose = this._resolvedResult.dispose;
			if (fixtureDispose) {
				runDispose(() => fixtureDispose.call(this._resolvedResult));
			}
		}
		this._resolvedResult = undefined;

		for (const d of this._disposables) {
			runDispose(() => d.dispose());
		}
		this._disposables.length = 0;

		try {
			removeStyles(this._injectedElements, this._adoptedSheets, this._styleTarget);
		} catch (err) {
			captureError(err);
		}

		if (promises.length === 0) {
			return Promise.resolve(errors);
		}
		return Promise.all(promises).then(() => errors);
	}
}
