const styles = {
  scrollContainer: {
    flex: 1,
    overflow: 'auto',
    backgroundColor: 'var(--component-explorer-editor-background)',
  } as React.CSSProperties,
  emptyState: {
    flex: 1,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: 'var(--component-explorer-editor-background)',
  } as React.CSSProperties,
  emptyText: {
    color: 'var(--component-explorer-descriptionForeground)',
    fontSize: '14px',
  } as React.CSSProperties,
  variantsHeader: {
    marginBottom: '12px',
  } as React.CSSProperties,
  variantsTitle: {
    fontSize: '13px',
    fontWeight: 500,
    color: 'var(--component-explorer-foreground)',
  } as React.CSSProperties,
  variantsContent: {
    display: 'flex',
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: '16px',
  } as React.CSSProperties,
  headingLink: {
    textDecoration: 'none',
    color: 'inherit',
  } as React.CSSProperties,
};
