export type DebugSplitOrientation = 'horizontal' | 'vertical';
export type DebugDockZone = 'center' | 'left' | 'right' | 'top' | 'bottom';

export interface DebugStackNode {
  readonly type: 'stack';
  readonly id: string;
  readonly entryKeys: readonly string[];
  readonly activeEntryKey: string;
}

export interface DebugSplitNode {
  readonly type: 'split';
  readonly id: string;
  readonly orientation: DebugSplitOrientation;
  readonly ratio: number;
  readonly first: DebugWorkbenchNode;
  readonly second: DebugWorkbenchNode;
}

export type DebugWorkbenchNode = DebugStackNode | DebugSplitNode;

let nextNodeId = 0;

export function createDebugWorkbenchLayout(
  entryKeys: readonly string[],
  activeEntryKey: string | undefined,
): DebugWorkbenchNode {
  if (entryKeys.length === 0) {
    throw new Error('A debug workbench requires at least one entry');
  }
  return createStack(entryKeys, activeEntryKey);
}

export function getDebugWorkbenchEntryOrder(node: DebugWorkbenchNode): readonly string[] {
  return node.type === 'stack'
    ? node.entryKeys
    : [...getDebugWorkbenchEntryOrder(node.first), ...getDebugWorkbenchEntryOrder(node.second)];
}

export function getVisibleDebugEntryKeys(node: DebugWorkbenchNode): ReadonlySet<string> {
  const result = new Set<string>();
  visitStacks(node, stack => result.add(stack.activeEntryKey));
  return result;
}

export function getFirstDebugStackId(node: DebugWorkbenchNode): string {
  return node.type === 'stack' ? node.id : getFirstDebugStackId(node.first);
}

export function reconcileDebugWorkbenchLayout(
  node: DebugWorkbenchNode,
  entryKeys: readonly string[],
  activeEntryKey: string | undefined,
): DebugWorkbenchNode {
  if (entryKeys.length === 0) {
    throw new Error('A debug workbench requires at least one entry');
  }

  const allowedKeys = new Set(entryKeys);
  let result = pruneEntries(node, allowedKeys);
  if (!result) {
    return createDebugWorkbenchLayout(entryKeys, activeEntryKey);
  }

  const presentKeys = new Set(getDebugWorkbenchEntryOrder(result));
  const missingKeys = entryKeys.filter(key => !presentKeys.has(key));
  if (missingKeys.length > 0) {
    const firstStackId = getFirstDebugStackId(result);
    const firstStack = findStack(result, firstStackId);
    if (!firstStack) {
      throw new Error(`Debug stack "${firstStackId}" is missing`);
    }
    result = replaceStack(result, firstStackId, {
      ...firstStack,
      entryKeys: [...firstStack.entryKeys, ...missingKeys],
    });
  }

  return activeEntryKey && allowedKeys.has(activeEntryKey)
    ? activateDebugEntry(result, activeEntryKey)
    : result;
}

export function activateDebugEntry(
  node: DebugWorkbenchNode,
  entryKey: string,
): DebugWorkbenchNode {
  return mapStacks(node, stack => stack.entryKeys.includes(entryKey)
    ? stack.activeEntryKey === entryKey
      ? stack
      : { ...stack, activeEntryKey: entryKey }
    : stack);
}

export function reorderDebugEntry(
  node: DebugWorkbenchNode,
  entryKey: string,
  targetEntryKey: string,
  before: boolean,
): DebugWorkbenchNode {
  if (entryKey === targetEntryKey) return node;
  const targetStack = findStackContaining(node, targetEntryKey);
  if (!targetStack) return node;
  const withoutEntry = removeEntry(node, entryKey);
  if (!withoutEntry) return node;
  const currentTargetStack = findStack(withoutEntry, targetStack.id);
  if (!currentTargetStack) return node;
  const targetIndex = currentTargetStack.entryKeys.indexOf(targetEntryKey);
  const index = targetIndex + (before ? 0 : 1);
  return replaceStack(withoutEntry, currentTargetStack.id, {
    ...currentTargetStack,
    entryKeys: insertAt(currentTargetStack.entryKeys, index, entryKey),
    activeEntryKey: entryKey,
  });
}

export function dockDebugEntry(
  node: DebugWorkbenchNode,
  entryKey: string,
  targetStackId: string,
  zone: DebugDockZone,
): DebugWorkbenchNode {
  const sourceStack = findStackContaining(node, entryKey);
  const targetStack = findStack(node, targetStackId);
  if (!sourceStack || !targetStack) return node;

  if (zone === 'center') {
    if (sourceStack.id === targetStack.id) {
      return activateDebugEntry(node, entryKey);
    }
    const withoutEntry = removeEntry(node, entryKey);
    if (!withoutEntry) return node;
    const currentTarget = findStack(withoutEntry, targetStackId);
    if (!currentTarget) return node;
    return replaceStack(withoutEntry, targetStackId, {
      ...currentTarget,
      entryKeys: [...currentTarget.entryKeys, entryKey],
      activeEntryKey: entryKey,
    });
  }

  if (sourceStack.id === targetStack.id && sourceStack.entryKeys.length === 1) {
    return node;
  }
  const withoutEntry = removeEntry(node, entryKey);
  if (!withoutEntry) return node;
  const currentTarget = findStack(withoutEntry, targetStackId);
  if (!currentTarget) return node;

  const newStack = createStack([entryKey], entryKey);
  const horizontal = zone === 'left' || zone === 'right';
  const before = zone === 'left' || zone === 'top';
  const split: DebugSplitNode = {
    type: 'split',
    id: createNodeId('split'),
    orientation: horizontal ? 'horizontal' : 'vertical',
    ratio: 0.5,
    first: before ? newStack : currentTarget,
    second: before ? currentTarget : newStack,
  };
  return replaceNode(withoutEntry, targetStackId, split);
}

export function updateDebugSplitRatio(
  node: DebugWorkbenchNode,
  splitId: string,
  ratio: number,
): DebugWorkbenchNode {
  if (node.type === 'stack') return node;
  if (node.id === splitId) {
    return { ...node, ratio: clampRatio(ratio) };
  }
  const first = updateDebugSplitRatio(node.first, splitId, ratio);
  const second = updateDebugSplitRatio(node.second, splitId, ratio);
  return first === node.first && second === node.second ? node : { ...node, first, second };
}

function createStack(
  entryKeys: readonly string[],
  activeEntryKey: string | undefined,
): DebugStackNode {
  return {
    type: 'stack',
    id: createNodeId('stack'),
    entryKeys: [...entryKeys],
    activeEntryKey: activeEntryKey && entryKeys.includes(activeEntryKey)
      ? activeEntryKey
      : entryKeys[0],
  };
}

function createNodeId(prefix: string): string {
  return `${prefix}-${nextNodeId++}`;
}

function mapStacks(
  node: DebugWorkbenchNode,
  mapper: (stack: DebugStackNode) => DebugStackNode,
): DebugWorkbenchNode {
  if (node.type === 'stack') return mapper(node);
  const first = mapStacks(node.first, mapper);
  const second = mapStacks(node.second, mapper);
  return first === node.first && second === node.second ? node : { ...node, first, second };
}

function visitStacks(node: DebugWorkbenchNode, visitor: (stack: DebugStackNode) => void): void {
  if (node.type === 'stack') {
    visitor(node);
    return;
  }
  visitStacks(node.first, visitor);
  visitStacks(node.second, visitor);
}

function findStackContaining(node: DebugWorkbenchNode, entryKey: string): DebugStackNode | undefined {
  if (node.type === 'stack') return node.entryKeys.includes(entryKey) ? node : undefined;
  return findStackContaining(node.first, entryKey) ?? findStackContaining(node.second, entryKey);
}

function findStack(node: DebugWorkbenchNode, stackId: string): DebugStackNode | undefined {
  if (node.type === 'stack') return node.id === stackId ? node : undefined;
  return findStack(node.first, stackId) ?? findStack(node.second, stackId);
}

function removeEntry(node: DebugWorkbenchNode, entryKey: string): DebugWorkbenchNode | undefined {
  if (node.type === 'stack') {
    if (!node.entryKeys.includes(entryKey)) return node;
    const entryKeys = node.entryKeys.filter(key => key !== entryKey);
    if (entryKeys.length === 0) return undefined;
    return {
      ...node,
      entryKeys,
      activeEntryKey: node.activeEntryKey === entryKey ? entryKeys[0] : node.activeEntryKey,
    };
  }
  const first = removeEntry(node.first, entryKey);
  const second = removeEntry(node.second, entryKey);
  if (!first) return second;
  if (!second) return first;
  return first === node.first && second === node.second ? node : { ...node, first, second };
}

function pruneEntries(
  node: DebugWorkbenchNode,
  allowedKeys: ReadonlySet<string>,
): DebugWorkbenchNode | undefined {
  if (node.type === 'stack') {
    const entryKeys = node.entryKeys.filter(key => allowedKeys.has(key));
    if (entryKeys.length === 0) return undefined;
    const activeEntryKey = entryKeys.includes(node.activeEntryKey)
      ? node.activeEntryKey
      : entryKeys[0];
    if (entryKeys.length === node.entryKeys.length && activeEntryKey === node.activeEntryKey) {
      return node;
    }
    return {
      ...node,
      entryKeys,
      activeEntryKey,
    };
  }

  const first = pruneEntries(node.first, allowedKeys);
  const second = pruneEntries(node.second, allowedKeys);
  if (!first) return second;
  if (!second) return first;
  return first === node.first && second === node.second ? node : { ...node, first, second };
}

function replaceStack(
  node: DebugWorkbenchNode,
  stackId: string,
  replacement: DebugStackNode,
): DebugWorkbenchNode {
  return replaceNode(node, stackId, replacement);
}

function replaceNode(
  node: DebugWorkbenchNode,
  nodeId: string,
  replacement: DebugWorkbenchNode,
): DebugWorkbenchNode {
  if (node.id === nodeId) return replacement;
  if (node.type === 'stack') return node;
  const first = replaceNode(node.first, nodeId, replacement);
  const second = replaceNode(node.second, nodeId, replacement);
  return first === node.first && second === node.second ? node : { ...node, first, second };
}

function insertAt(values: readonly string[], index: number, value: string): readonly string[] {
  return [...values.slice(0, index), value, ...values.slice(index)];
}

function clampRatio(ratio: number): number {
  return Math.max(0.2, Math.min(0.8, ratio));
}
