import {
  isInteractiveOutput,
  type DebugPanelActivation,
  type DebugPanelChannel,
  type IDisposable,
} from './fixtureApi.js';

export const OUTPUT_DEBUG_PANEL_ID = '$output';

export interface ActiveDebugPanelSession extends IDisposable {
  sendAction(action: unknown): void;
}

type InputListener = (value: unknown, input: unknown) => void;

export class FixtureInputRuntime {
  private readonly _listeners = new Map<string, Set<InputListener>>();

  constructor(private _input: unknown) {}

  watch(key: string, listener: InputListener): IDisposable {
    let listeners = this._listeners.get(key);
    if (!listeners) {
      listeners = new Set();
      this._listeners.set(key, listeners);
    }
    listeners.add(listener);
    listener(readProperty(this._input, key), this._input);

    let disposed = false;
    return {
      dispose: () => {
        if (disposed) return;
        disposed = true;
        listeners.delete(listener);
        if (listeners.size === 0) {
          this._listeners.delete(key);
        }
      },
    };
  }

  update(input: unknown): boolean {
    const changedKeys = getChangedKeys(this._input, input);
    if (changedKeys.length === 0) {
      this._input = input;
      return true;
    }
    if (changedKeys.some(key => !this._listeners.has(key))) {
      return false;
    }

    this._input = input;
    for (const key of changedKeys) {
      const listeners = this._listeners.get(key);
      if (!listeners) continue;
      const value = readProperty(input, key);
      for (const listener of [...listeners]) {
        listener(value, input);
      }
    }
    return true;
  }
}

export class FixtureDebugRuntime implements IDisposable {
  private readonly _activations = new Map<string, DebugPanelActivation<unknown, unknown>>();
  private readonly _activeSessions = new Set<ActiveDebugPanelSession>();
  private _output: unknown;
  private _hasOutput = false;

  connect(
    panelId: string,
    activate: DebugPanelActivation<unknown, unknown>,
  ): IDisposable {
    if (this._activations.has(panelId)) {
      throw new Error(`Debug panel "${panelId}" is already connected`);
    }
    this._activations.set(panelId, activate);
    return {
      dispose: () => {
        if (this._activations.get(panelId) === activate) {
          this._activations.delete(panelId);
        }
      },
    };
  }

  setOutput(output: unknown): void {
    this._output = output;
    this._hasOutput = output !== undefined;
  }

  get hasOutput(): boolean {
    return this._hasOutput;
  }

  get outputEditable(): boolean {
    return isInteractiveOutput(this._output);
  }

  getOutputSnapshot(): unknown {
    return isInteractiveOutput(this._output)
      ? this._output.getSnapshot()
      : this._output;
  }

  activate(panelId: string, publish: (state: unknown) => void): ActiveDebugPanelSession {
    const actionListeners = new Set<(action: unknown) => void>();
    const channel: DebugPanelChannel<unknown, unknown> = {
      publish,
      onAction(listener) {
        actionListeners.add(listener);
        return {
          dispose: () => {
            actionListeners.delete(listener);
          },
        };
      },
    };

    let activation: void | IDisposable;
    if (panelId === OUTPUT_DEBUG_PANEL_ID) {
      activation = this._activateOutput(channel);
    } else {
      const provider = this._activations.get(panelId);
      if (!provider) {
        throw new Error(`Debug panel "${panelId}" is not connected`);
      }
      activation = provider(channel);
    }

    let disposed = false;
    const session: ActiveDebugPanelSession = {
      sendAction(action) {
        if (disposed) return;
        for (const listener of [...actionListeners]) {
          listener(action);
        }
      },
      dispose: () => {
        if (disposed) return;
        disposed = true;
        actionListeners.clear();
        this._activeSessions.delete(session);
        const result = activation?.dispose();
        if (result instanceof Promise) {
          result.catch(error => console.error('Failed to dispose debug panel activation', error));
        }
      },
    };
    this._activeSessions.add(session);
    return session;
  }

  dispose(): void {
    for (const session of [...this._activeSessions]) {
      session.dispose();
    }
    this._activations.clear();
    this._output = undefined;
    this._hasOutput = false;
  }

  private _activateOutput(
    channel: DebugPanelChannel<unknown, unknown>,
  ): void | IDisposable {
    if (!this._hasOutput) {
      throw new Error('Fixture has no output');
    }
    if (isInteractiveOutput(this._output)) {
      return this._output.activate(channel);
    }
    channel.publish(this._output);
  }
}

function readProperty(input: unknown, key: string): unknown {
  return isRecord(input) ? input[key] : undefined;
}

function getChangedKeys(previous: unknown, next: unknown): readonly string[] {
  const previousRecord = isRecord(previous) ? previous : {};
  const nextRecord = isRecord(next) ? next : {};
  const keys = new Set([...Object.keys(previousRecord), ...Object.keys(nextRecord)]);
  return [...keys].filter(key => !Object.is(previousRecord[key], nextRecord[key]));
}

function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}
