import type { FixtureNode } from '../core/FixtureNode.js';
import type { FixtureExport } from '../core/fixtureApi.js';
import type { DisposeReport, ExceptionError, RenderEvent, RenderReport } from '../core/ErrorInfo.js';
import type { ExplorerRuntime, FixtureModules } from '../core/index.js';
import type { HeadlessApi, HeadlessFlatFixture, IComponentExplorerGlobal } from '@vscode/component-explorer-common';
import { createFixtureTree } from '../core/FixtureNode.js';
import { ComponentRendering } from '../core/ComponentRenderer.js';
import { runtimeVersion } from '../runtimeVersion.js';

declare global {
	interface Window extends IComponentExplorerGlobal { }
}

export class HeadlessMode implements ExplorerRuntime {
	/** Random ID generated on construction — changes on full page reload. */
	readonly pageInstanceId = Math.random().toString(36).slice(2);
	private _updateVersion = 0;
	private _root: FixtureNode;
	private _fixtureModules: FixtureModules;
	private _loadError: string | undefined;
	private _loadPromise: Promise<void>;
	private _currentRendering: ComponentRendering | undefined;
	private _currentContainer: HTMLElement | undefined;

	constructor(
		private readonly _containerElement: HTMLElement,
		loadFixtures: Promise<FixtureModules>,
	) {
		this._fixtureModules = {};
		this._root = this._buildTree(this._fixtureModules);
		this._loadPromise = loadFixtures.then(
			modules => {
				this._fixtureModules = modules;
				this._root = this._buildTree(modules);
				this._loadError = undefined;
				this._updateVersion++;
				const count = this._flattenFixtures(this._root).length;
				console.log('[headless] Fixtures loaded, version:', this._updateVersion, 'fixtures:', count);
			},
			error => {
				this._loadError = error instanceof Error ? (error.stack ?? error.message) : String(error);
				this._updateVersion++;
				console.error('[headless] Failed to load fixtures:', this._loadError);
			},
		);
		this._installGlobalApi();

		console.log('[headless] Initialized, pageInstanceId:', this.pageInstanceId);
	}

	get updateVersion(): number {
		return this._updateVersion;
	}

	updateFixtures(fixtureModules: FixtureModules): void {
		this._fixtureModules = fixtureModules;
		this._root = this._buildTree(fixtureModules);
		this._loadError = undefined;
		this._updateVersion++;
		const count = this._flattenFixtures(this._root).length;
		console.log('[headless] Registry rebuilt, version:', this._updateVersion, 'fixtures:', count);
	}

	bumpVersion(): void {
		this._updateVersion++;
		console.log('[headless] Version bumped:', this._updateVersion);
	}

	async listFixtures(): Promise<HeadlessFlatFixture[]> {
		await this._loadPromise;
		if (this._loadError) {
			throw new Error(this._loadError);
		}
		return this._flattenFixtures(this._root);
	}

	async disposeCurrentFixture(): Promise<DisposeReport> {
		const events: RenderEvent[] = [];
		const errors: ExceptionError[] = [];
		const stop = this._captureEvents(events);
		try {
			if (this._currentRendering) {
				const r = this._currentRendering;
				this._currentRendering = undefined;
				try {
					const disposeErrors = await r.dispose();
					errors.push(...disposeErrors);
				} catch (e) {
					errors.push(this._toError(e));
				}
			}
			if (this._currentContainer) {
				try {
					this._currentContainer.remove();
				} catch (e) {
					errors.push(this._toError(e));
				}
				this._currentContainer = undefined;
			}
			// Give one frame for unhandled rejections / async window errors
			// triggered during dispose to surface before we stop capturing.
			await new Promise<void>(resolve => requestAnimationFrame(() => resolve()));
		} finally {
			stop();
		}
		const hasError = errors.length > 0 || events.some(e => e.type === 'console.error' || e.type === 'window.error' || e.type === 'window.unhandledrejection');
		return { hasError, errors, events };
	}

	async renderFixture(fixtureId: string, input?: unknown): Promise<RenderReport> {
		await this._loadPromise;
		if (this._loadError) {
			throw new Error(this._loadError);
		}
		const node = this._findFixtureNode(this._root, fixtureId);
		if (!node || !node.component) {
			const allIds = this._flattenFixtures(this._root).map(f => f.fixtureId);
			const suggestions = findClosestMatches(fixtureId, allIds, 5);
			const suggestionText = suggestions.length > 0
				? `\nDid you mean one of these?\n${suggestions.map(s => `  - ${s}`).join('\n')}`
				: '';
			throw new Error('Fixture not found: ' + fixtureId + suggestionText);
		}

		if (input !== undefined && (typeof input !== 'object' || input === null || Array.isArray(input))) {
			throw new Error(
				`Fixture input must be a JSON object (or undefined) — received ${input === null ? 'null' : Array.isArray(input) ? 'an array' : typeof input
				}.`,
			);
		}

		const previousDisposeReport = await this.disposeCurrentFixture();

		const container = document.createElement('div');
		container.style.display = 'inline-block';
		this._containerElement.appendChild(container);
		this._currentContainer = container;

		const def = node.component;

		const events: RenderEvent[] = [];
		let error: ExceptionError | undefined;

		const setError = (e: ExceptionError) => {
			if (!error) { error = e; }
		};

		const stop = this._captureEvents(events);

		let output: unknown;
		const startTime = performance.now();
		let syncTimeMs: number | undefined;
		try {
			const rendering = new ComponentRendering(container, def, { kind: 'headless', interactive: false }, input);
			syncTimeMs = performance.now() - startTime;
			this._currentRendering = rendering;

			await rendering.waitForRendering();
			output = rendering.hasOutput ? rendering.getOutputSnapshot() : undefined;
		} catch (e) {
			setError(this._toError(e));
		} finally {
			stop();
		}

		if (!error) {
			await new Promise<void>(resolve => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));
		}

		const totalTimeMs = performance.now() - startTime;

		const hasError = !!error || events.some(e => e.type !== 'console.log' && e.type !== 'console.warn');
		const renderTimeMs = { sync: Math.round(syncTimeMs ?? totalTimeMs), total: Math.round(totalTimeMs) };
		const previousDispose = (previousDisposeReport.hasError || previousDisposeReport.events.length > 0 || previousDisposeReport.errors.length > 0)
			? previousDisposeReport
			: undefined;
		return { hasError, error, events, output, renderTimeMs, previousDispose };
	}

	/**
	 * Install console + window error/rejection listeners that push into `events`.
	 * Returns a `stop` function that uninstalls them. Listeners do not need to be
	 * uninstalled in a `finally` ordering — multiple captures may overlap; the
	 * outer `console.*` is restored to whatever was the previous value (LIFO via
	 * the closure over `originalError` etc.).
	 */
	private _captureEvents(events: RenderEvent[]): () => void {
		const originalError = console.error;
		const originalWarn = console.warn;
		const originalLog = console.log;
		const stackFromArgs = (args: unknown[]): string | undefined => {
			for (const a of args) {
				if (a instanceof Error && a.stack) { return a.stack; }
			}
			return undefined;
		};
		console.error = (...args: unknown[]) => {
			events.push({ type: 'console.error', message: args.map(String).join(' '), stack: stackFromArgs(args) });
			originalError.apply(console, args);
		};
		console.warn = (...args: unknown[]) => {
			events.push({ type: 'console.warn', message: args.map(String).join(' '), stack: stackFromArgs(args) });
			originalWarn.apply(console, args);
		};
		console.log = (...args: unknown[]) => {
			events.push({ type: 'console.log', message: args.map(String).join(' ') });
			originalLog.apply(console, args);
		};
		const errorHandler = (event: ErrorEvent) => {
			events.push({ type: 'window.error', message: event.message, stack: event.error?.stack });
		};
		const rejectionHandler = (event: PromiseRejectionEvent) => {
			const reason = event.reason;
			const message = reason instanceof Error ? reason.message : String(reason);
			const stack = reason instanceof Error ? reason.stack : undefined;
			events.push({ type: 'window.unhandledrejection', message, stack });
		};
		window.addEventListener('error', errorHandler);
		window.addEventListener('unhandledrejection', rejectionHandler);
		return () => {
			console.error = originalError;
			console.warn = originalWarn;
			console.log = originalLog;
			window.removeEventListener('error', errorHandler);
			window.removeEventListener('unhandledrejection', rejectionHandler);
		};
	}

	private _toError(e: unknown): ExceptionError {
		if (e instanceof Error) {
			return { message: e.message, stack: e.stack };
		}
		if (e && typeof e === 'object' && 'message' in e) {
			return {
				message: String((e as Record<string, unknown>).message),
				stack: String((e as Record<string, unknown>).stack ?? '') || undefined,
			};
		}
		return { message: String(e) };
	}

	private _buildTree(fixtureModules: FixtureModules): FixtureNode {
		const fixtures = new Map<string, FixtureExport>();
		for (const [path, module] of Object.entries(fixtureModules)) {
			const fixture = module.default;
			if (fixture && typeof fixture === 'object') {
				fixtures.set(path, fixture as FixtureExport);
			}
		}
		return createFixtureTree(fixtures);
	}

	private _flattenFixtures(node: FixtureNode, groupPath: string[] = [], inheritedLabels: readonly string[] = []): HeadlessFlatFixture[] {
		const effectiveLabels = inheritedLabels.length > 0 && node.labels.length > 0
			? [...new Set([...inheritedLabels, ...node.labels])]
			: node.labels.length > 0 ? [...node.labels]
				: [...inheritedLabels];
		const results: HeadlessFlatFixture[] = [];
		if (node.type === 'component') {
			results.push({
				fixtureId: node.id.value,
				fixtureName: node.name,
				groupPath,
				background: node.component?.background ?? 'light',
				labels: effectiveLabels,
				expectedVisualDescriptions: node.component?.expectedVisualDescriptions ?? [],
				inputSchema: node.component?.inputSchema,
			});
		}
		for (const child of node.children ?? []) {
			const nextPath = node.id.value ? [...groupPath, node.name] : groupPath;
			results.push(...this._flattenFixtures(child, nextPath, effectiveLabels));
		}
		return results;
	}

	private _findFixtureNode(node: FixtureNode, fixtureId: string): FixtureNode | undefined {
		if (node.id.value === fixtureId) return node;
		for (const child of node.children ?? []) {
			const found = this._findFixtureNode(child, fixtureId);
			if (found) return found;
		}
		return undefined;
	}

	private _installGlobalApi(): void {
		const self = this;
		const api: HeadlessApi = {
			pageInstanceId: this.pageInstanceId,
			get updateVersion() { return self._updateVersion; },
			runtimeVersion: runtimeVersion.toString(),
			listFixtures: () => this.listFixtures(),
			renderFixture: (id, input) => this.renderFixture(id, input),
			disposeCurrentFixture: () => this.disposeCurrentFixture(),
		};
		window.__componentExplorer__ = api;
	}
}

function levenshteinDistance(a: string, b: string): number {
	const la = a.length, lb = b.length;
	const dp = Array.from({ length: la + 1 }, () => new Array<number>(lb + 1));
	for (let i = 0; i <= la; i++) dp[i][0] = i;
	for (let j = 0; j <= lb; j++) dp[0][j] = j;
	for (let i = 1; i <= la; i++) {
		for (let j = 1; j <= lb; j++) {
			dp[i][j] = a[i - 1] === b[j - 1]
				? dp[i - 1][j - 1]
				: 1 + Math.min(dp[i - 1][j - 1], dp[i - 1][j], dp[i][j - 1]);
		}
	}
	return dp[la][lb];
}

function findClosestMatches(target: string, candidates: string[], count: number): string[] {
	return candidates
		.map(c => ({ id: c, dist: levenshteinDistance(target.toLowerCase(), c.toLowerCase()) }))
		.sort((a, b) => a.dist - b.dist)
		.slice(0, count)
		.map(c => c.id);
}
