import { observableValue, type IReader, type ISettableObservable } from '@vscode/observables';
import type { PageMode } from '../core/index.js';
import { resolveViewport } from '../core/index.js';

export type PagePreviewMode = 'fit' | 'responsive' | 'actual';

export interface PageViewportSettings {
  readonly viewportIndex: number;
  readonly width: number;
  readonly height: number;
  readonly mode: PagePreviewMode;
}

interface StoredPageViewportSettings {
  readonly viewportIndex?: number;
  readonly width?: number;
  readonly height?: number;
  readonly mode?: PagePreviewMode;
}

export interface PagePreviewGeometry {
  readonly logicalWidth: number;
  readonly logicalHeight: number;
  readonly scale: number;
  readonly visualWidth: number;
  readonly visualHeight: number;
}

const STORAGE_KEY = 'component-explorer:pageViewports';
const MIN_VIEWPORT_SIZE = 1;
const MAX_VIEWPORT_SIZE = 10_000;

function clampDimension(value: number | undefined, fallback: number): number {
  if (value === undefined || !Number.isFinite(value)) {
    return fallback;
  }
  return Math.min(MAX_VIEWPORT_SIZE, Math.max(MIN_VIEWPORT_SIZE, Math.round(value)));
}

function clampViewportIndex(value: number | undefined, pageMode: PageMode): number {
  if (value === undefined || !Number.isInteger(value)) {
    return 0;
  }
  return Math.min(Math.max(value, 0), Math.max(0, pageMode.viewports.length - 1));
}

function isPagePreviewMode(value: unknown): value is PagePreviewMode {
  return value === 'fit' || value === 'responsive' || value === 'actual';
}

function defaultViewport(pageMode: PageMode, viewportIndex: number): { width: number; height: number } {
  const preset = pageMode.viewports[viewportIndex] ?? 'desktop';
  return resolveViewport(preset);
}

function resolveSettings(
  stored: StoredPageViewportSettings | undefined,
  pageMode: PageMode,
): PageViewportSettings {
  const viewportIndex = clampViewportIndex(stored?.viewportIndex, pageMode);
  const fallback = defaultViewport(pageMode, viewportIndex);
  return {
    viewportIndex,
    width: clampDimension(stored?.width, fallback.width),
    height: clampDimension(stored?.height, fallback.height),
    mode: isPagePreviewMode(stored?.mode) ? stored.mode : 'fit',
  };
}

export function calculatePagePreviewGeometry(
  settings: PageViewportSettings,
  availableWidth: number,
  availableHeight = 0,
): PagePreviewGeometry {
  const usableWidth = Number.isFinite(availableWidth)
    ? Math.max(0, Math.floor(availableWidth))
    : 0;
  const usableHeight = Number.isFinite(availableHeight)
    ? Math.max(0, Math.floor(availableHeight))
    : 0;
  const logicalWidth = settings.mode === 'responsive' && usableWidth > 0
    ? usableWidth
    : settings.width;
  const logicalHeight = settings.mode === 'responsive' && usableHeight > 0
    ? usableHeight
    : settings.height;
  const scale = settings.mode === 'fit' && usableWidth > 0
    ? Math.min(1, usableWidth / logicalWidth)
    : 1;

  return {
    logicalWidth,
    logicalHeight,
    scale,
    visualWidth: logicalWidth * scale,
    visualHeight: logicalHeight * scale,
  };
}

export class FixtureViewportStore {
  private readonly _values: ISettableObservable<Record<string, StoredPageViewportSettings>>;

  constructor() {
    this._values = observableValue('fixturePageViewports', this._load());
  }

  read(reader: IReader, fixtureId: string, pageMode: PageMode): PageViewportSettings {
    return resolveSettings(this._values.read(reader)[fixtureId], pageMode);
  }

  get(fixtureId: string, pageMode: PageMode): PageViewportSettings {
    return resolveSettings(this._values.get()[fixtureId], pageMode);
  }

  selectViewport(fixtureId: string, pageMode: PageMode, viewportIndex: number): void {
    const index = clampViewportIndex(viewportIndex, pageMode);
    const viewport = defaultViewport(pageMode, index);
    const current = this.get(fixtureId, pageMode);
    this._set(fixtureId, {
      viewportIndex: index,
      width: viewport.width,
      height: viewport.height,
      mode: current.mode,
    });
  }

  setWidth(fixtureId: string, pageMode: PageMode, width: number): void {
    const current = this.get(fixtureId, pageMode);
    this._set(fixtureId, { ...current, width: clampDimension(width, current.width) });
  }

  setHeight(fixtureId: string, pageMode: PageMode, height: number): void {
    const current = this.get(fixtureId, pageMode);
    this._set(fixtureId, { ...current, height: clampDimension(height, current.height) });
  }

  setMode(fixtureId: string, pageMode: PageMode, mode: PagePreviewMode): void {
    const current = this.get(fixtureId, pageMode);
    this._set(fixtureId, { ...current, mode });
  }

  private _set(fixtureId: string, settings: StoredPageViewportSettings): void {
    const next = { ...this._values.get(), [fixtureId]: settings };
    this._values.set(next, undefined);
    this._persist(next);
  }

  private _load(): Record<string, StoredPageViewportSettings> {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) {
        return {};
      }
      const parsed: unknown = JSON.parse(raw);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        return parsed as Record<string, StoredPageViewportSettings>;
      }
    } catch {
      // Ignore malformed or inaccessible persisted UI state.
    }
    return {};
  }

  private _persist(value: Record<string, StoredPageViewportSettings>): void {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(value));
    } catch {
      // Ignore storage failures; viewport controls remain usable for this session.
    }
  }
}
