import type { FixtureExport, RenderHost } from '../core/fixtureApi.js';
import type { FixtureNode } from '../core/FixtureNode.js';
import type { ExplorerRuntime, FixtureModules } from '../core/index.js';
import type { ExceptionError, RenderEventType } from '../core/ErrorInfo.js';
import { createFixtureTree } from '../core/FixtureNode.js';
import { ComponentRendering } from '../core/ComponentRenderer.js';
import type { ActiveDebugPanelSession } from '../core/FixtureInteractionRuntime.js';

interface DebugPanelRequest {
	privateSession?: ActiveDebugPanelSession;
	readonly panelId: string;
}

export class EmbeddedMode implements ExplorerRuntime {
	private _root: FixtureNode | undefined;
	private _rendering: ComponentRendering | undefined;
	private _resizeObserver: ResizeObserver | undefined;
	private _errorPosted = false;
	private _originalConsoleError: typeof console.error | undefined;
	private _originalConsoleWarn: typeof console.warn | undefined;
	private readonly _debugPanelRequests = new Map<string, DebugPanelRequest>();
	private _input: unknown;
	private _renderHost: RenderHost = { kind: 'embedded', interactive: false };
	private _initialized = window.parent === window;

	constructor(
		private readonly _container: HTMLElement,
		private readonly _fixtureId: string,
		loadSourceModule: Promise<FixtureModules>,
	) {
		this._setupErrorCapture();
		this._setupDebugPanelTransport();
		loadSourceModule.then(
			modules => {
				this._root = this._buildTree(modules);
				if (this._initialized) {
					this._render();
				}
			},
			error => {
				const message = error instanceof Error ? (error.stack ?? error.message) : String(error);
				console.error('[EmbeddedMode] Failed to load fixtures:', message);
				this._container.innerHTML = '';
				const el = document.createElement('div');
				el.style.cssText = 'padding:16px;color:#f44;font-size:13px;font-family:monospace;white-space:pre-wrap;user-select:text;cursor:text;';
				el.textContent = `Failed to load fixture:\n${message}`;
				this._container.appendChild(el);
				this._postError({ message: error instanceof Error ? error.message : String(error), stack: error instanceof Error ? error.stack : undefined });
			},
		);
		if (!this._initialized) {
			window.parent.postMessage({ type: 'component-explorer:embedded-loaded' }, '*');
		}
	}

	private _setupDebugPanelTransport(): void {
		window.addEventListener('message', event => {
			if (event.source !== window.parent) return;
			const data = event.data;
			if (data?.type === 'component-explorer:embedded-init') {
				if (this._initialized) return;
				this._initialized = true;
				this._input = data.input;
				this._renderHost = data.host?.kind === 'explorer-ui'
					? { kind: 'explorer-ui', interactive: true }
					: { kind: 'embedded', interactive: false };
				if (this._root) {
					this._render();
				}
			} else if (data?.type === 'component-explorer:embedded-input') {
				this._updateInput(data.input);
			} else if (data?.type === 'component-explorer:debug-panel-activate') {
				const sessionId = typeof data.sessionId === 'string' ? data.sessionId : '';
				const panelId = typeof data.panelId === 'string' ? data.panelId : '';
				if (!sessionId || !panelId) return;
				const previous = this._debugPanelRequests.get(sessionId);
				previous?.privateSession?.dispose();
				const request: DebugPanelRequest = { panelId };
				this._debugPanelRequests.set(sessionId, request);
				this._activateDebugPanel(sessionId, request);
			} else if (data?.type === 'component-explorer:debug-panel-action') {
				const sessionId = typeof data.sessionId === 'string' ? data.sessionId : '';
				this._debugPanelRequests.get(sessionId)?.privateSession?.sendAction(data.action);
			} else if (data?.type === 'component-explorer:debug-panel-deactivate') {
				const sessionId = typeof data.sessionId === 'string' ? data.sessionId : '';
				const request = this._debugPanelRequests.get(sessionId);
				request?.privateSession?.dispose();
				this._debugPanelRequests.delete(sessionId);
			}
		});
	}

	private _updateInput(input: unknown): void {
		this._input = input;
		if (!this._initialized || !this._rendering) return;
		if (!this._rendering.updateInput(input)) {
			this._render();
		}
	}

	private _setupErrorCapture(): void {
		// Intercept console.error and forward to parent
		this._originalConsoleError = console.error;
		console.error = (...args: unknown[]) => {
			this._postConsoleEvent('console.error', args.map(String).join(' '));
			this._originalConsoleError!.apply(console, args);
		};

		// Intercept console.warn and forward to parent
		this._originalConsoleWarn = console.warn;
		console.warn = (...args: unknown[]) => {
			this._postConsoleEvent('console.warn', args.map(String).join(' '));
			this._originalConsoleWarn!.apply(console, args);
		};

		window.addEventListener('error', (event) => {
			this._postError({ message: event.message, stack: event.error?.stack });
			this._postConsoleEvent('window.error', event.message, event.error?.stack);
		});
		window.addEventListener('unhandledrejection', (event) => {
			const reason = event.reason;
			const message = reason instanceof Error ? reason.message : String(reason);
			const stack = reason instanceof Error ? reason.stack : undefined;
			this._postError({ message, stack });
			this._postConsoleEvent('window.unhandledrejection', message, stack);
		});
	}

	private _postConsoleEvent(type: RenderEventType, message: string, stack?: string): void {
		window.parent.postMessage({
			type: 'component-explorer:console',
			eventType: type,
			message,
			stack,
		}, '*');
	}

	private _postError(error: ExceptionError): void {
		if (this._errorPosted) return;
		this._errorPosted = true;
		window.parent.postMessage({
			type: 'component-explorer:error',
			fixtureId: this._fixtureId,
			error,
		}, '*');
	}

	updateFixtures(fixtureModules: FixtureModules): void {
		this._root = this._buildTree(fixtureModules);
		this._render();
	}

	bumpVersion(): void {
		this._render();
	}

	private _render(): void {
		// Fire-and-forget — embedded mode has no dispose-report consumer.
		this._rendering?.dispose().catch(() => { /* noop */ });
		this._rendering = undefined;
		this._resizeObserver?.disconnect();
		this._resizeObserver = undefined;
		for (const request of this._debugPanelRequests.values()) {
			request.privateSession?.dispose();
			request.privateSession = undefined;
		}
		this._container.innerHTML = '';

		if (!this._root) return;

		const node = this._findNode(this._root, this._fixtureId);
		if (!node?.component) {
			console.error(`[EmbeddedMode] Fixture not found: ${this._fixtureId}`);
			return;
		}

		const component = { ...node.component, isolation: 'none' as const };
		this._errorPosted = false;

		// For component mode, make the container fit-content so the component's
		// natural width is measured (not constrained to the iframe viewport width).
		this._container.style.width = component.displayMode.type === 'component' ? 'fit-content' : '';

		try {
			const rendering = new ComponentRendering(this._container, component, this._renderHost, this._input);
			this._rendering = rendering;

			rendering.waitForRendering().then(() => {
				window.parent.postMessage({
					type: 'component-explorer:ready',
					fixtureId: this._fixtureId,
					hasOutput: rendering.hasOutput,
					outputEditable: rendering.outputEditable,
				}, '*');
				for (const [sessionId, request] of this._debugPanelRequests) {
					this._activateDebugPanel(sessionId, request);
				}
			}).catch((err) => {
					if (err && typeof err === 'object' && 'message' in err) {
						this._postError(err as ExceptionError);
					} else {
						this._postError({ message: err instanceof Error ? err.message : String(err), stack: err instanceof Error ? err.stack : undefined });
					}
				});
		} catch (err) {
			// Catch sync errors thrown during render
			this._postError({ message: err instanceof Error ? err.message : String(err), stack: err instanceof Error ? err.stack : undefined });
			console.error('[EmbeddedMode] Error during rendering:', err);
			return;
		}

		const rendering = this._rendering;
		const fixtureId = this._fixtureId;
		const postSize = () => {
			const rect = rendering.renderTarget.getBoundingClientRect();
			window.parent.postMessage({
				type: 'component-explorer:resize',
				fixtureId,
				width: rect.width,
				height: rect.height,
			}, '*');
		};

		this._resizeObserver = new ResizeObserver(postSize);
		this._resizeObserver.observe(rendering.renderTarget);
	}

	private _activateDebugPanel(sessionId: string, request: DebugPanelRequest): void {
		if (!this._rendering || request.privateSession) return;
		try {
			request.privateSession = this._rendering.activateDebugPanel(
				request.panelId,
				state => window.parent.postMessage({
					type: 'component-explorer:debug-panel-state',
					sessionId,
					state,
				}, '*'),
			);
		} catch (error) {
			this._postConsoleEvent(
				'console.error',
				`Failed to activate debug panel "${request.panelId}": ${error instanceof Error ? error.message : String(error)}`,
				error instanceof Error ? error.stack : undefined,
			);
		}
	}

	private _buildTree(fixtureModules: FixtureModules): FixtureNode {
		const fixtures = new Map<string, FixtureExport>();
		for (const [path, module] of Object.entries(fixtureModules)) {
			const fixture = module.default;
			if (fixture && typeof fixture === 'object') {
				fixtures.set(path, fixture as FixtureExport);
			}
		}
		return createFixtureTree(fixtures);
	}

	private _findNode(node: FixtureNode, id: string): FixtureNode | undefined {
		if (node.id.value === id) return node;
		for (const child of node.children ?? []) {
			const found = this._findNode(child, id);
			if (found) return found;
		}
		return undefined;
	}
}
