import { observableValue, type IReader } from '@vscode/observables';
import type { ComponentRendering } from '../core/ComponentRenderer.js';
import type { FixtureItem } from './ExplorerModel.js';

export interface FixtureDebugInfo {
  readonly fixture: FixtureItem;
  readonly rendering: ComponentRendering;
  readonly ready: boolean;
  readonly hasOutput: boolean;
  readonly outputEditable: boolean;
}

export class FixtureDebugStore {
  private readonly _entries = observableValue<ReadonlyMap<string, FixtureDebugInfo>>(
    this,
    new Map(),
  );

  read(reader: IReader, fixtureId: string): FixtureDebugInfo | undefined {
    return this._entries.read(reader).get(fixtureId);
  }

  get(fixtureId: string): FixtureDebugInfo | undefined {
    return this._entries.get().get(fixtureId);
  }

  setRendering(fixture: FixtureItem, rendering: ComponentRendering): void {
    this._set(fixture.id, {
      fixture,
      rendering,
      ready: false,
      hasOutput: false,
      outputEditable: false,
    });
  }

  markReady(fixture: FixtureItem, rendering: ComponentRendering): void {
    if (this._entries.get().get(fixture.id)?.rendering !== rendering) return;
    this._set(fixture.id, {
      fixture,
      rendering,
      ready: true,
      hasOutput: rendering.hasOutput,
      outputEditable: rendering.outputEditable,
    });
  }

  remove(fixtureId: string, rendering: ComponentRendering): void {
    const current = this._entries.get();
    if (current.get(fixtureId)?.rendering !== rendering) return;
    const next = new Map(current);
    next.delete(fixtureId);
    this._entries.set(next, undefined);
  }

  private _set(fixtureId: string, info: FixtureDebugInfo): void {
    const next = new Map(this._entries.get());
    next.set(fixtureId, info);
    this._entries.set(next, undefined);
  }
}
