import { observableValue, type ISettableObservable } from '@vscode/observables';
import {
  createDebugWorkbenchLayout,
  reconcileDebugWorkbenchLayout,
  type DebugWorkbenchNode,
} from './DebugWorkbenchLayout.js';

export class DebugWorkbenchStateStore {
  private readonly layouts = new Map<string, ISettableObservable<DebugWorkbenchNode>>();
  private readonly activeEntries = new Map<string, ISettableObservable<string | undefined>>();

  getLayout(
    workbenchId: string,
    entryKeys: readonly string[],
    activeEntryKey: string | undefined,
  ): ISettableObservable<DebugWorkbenchNode> {
    let layout = this.layouts.get(workbenchId);
    if (!layout) {
      layout = observableValue(
        this,
        createDebugWorkbenchLayout(entryKeys, activeEntryKey),
      );
      this.layouts.set(workbenchId, layout);
      return layout;
    }

    const current = layout.get();
    const next = reconcileDebugWorkbenchLayout(current, entryKeys, activeEntryKey);
    if (next !== current) layout.set(next, undefined);
    return layout;
  }

  getActiveEntry(workbenchId: string): ISettableObservable<string | undefined> {
    let activeEntry = this.activeEntries.get(workbenchId);
    if (!activeEntry) {
      activeEntry = observableValue<string | undefined>(this, undefined);
      this.activeEntries.set(workbenchId, activeEntry);
    }
    return activeEntry;
  }
}
