import * as React from 'react';
import { observableValue } from '@vscode/observables';
import { viewWithModel, ViewModel, prop } from '@vscode/observables-react';
import { ConsoleEventsStore, type ConsoleEvent } from '../core/ConsoleEventsStore.js';

class ConsolePanelModel extends ViewModel({
	store: prop.const<ConsoleEventsStore>(),
}) {
	readonly expanded = observableValue(this, false);

	get store(): ConsoleEventsStore { return this.props.store; }

	toggleExpanded(): void {
		this.expanded.set(!this.expanded.get(), undefined);
	}

	clear(): void {
		this.store.clear();
	}
}

export const ConsolePanel = viewWithModel(
	ConsolePanelModel,
	{ store: prop.const<ConsoleEventsStore>() },
	(reader, model) => {
		const store = model.store;
		const events = store.events.read(reader);
		const errorCount = store.errorCount.read(reader);
		const expanded = model.expanded.read(reader);

		if (events.length === 0) {
			return null;
		}

		return (
			<div style={panelStyles.container}>
				<button
					style={panelStyles.header}
					onClick={() => model.toggleExpanded()}
				>
					<span style={panelStyles.headerLeft}>
						<span style={panelStyles.chevron}>{expanded ? '▼' : '▶'}</span>
						<span>Console</span>
						{errorCount > 0 && (
							<span style={panelStyles.errorBadge}>{errorCount}</span>
						)}
						{events.length > errorCount && (
							<span style={panelStyles.warnBadge}>{events.length - errorCount}</span>
						)}
					</span>
					<button
						style={panelStyles.clearButton}
						onClick={(e) => { e.stopPropagation(); model.clear(); }}
						title="Clear console"
					>
						Clear
					</button>
				</button>
				{expanded && (
					<div style={panelStyles.content}>
						{events.map((event: ConsoleEvent) => (
							<ConsoleEventRow key={event.id} event={event} />
						))}
					</div>
				)}
			</div>
		);
	}
);

function ConsoleEventRow({ event }: { event: ConsoleEvent }): React.ReactElement {
	const [showStack, setShowStack] = React.useState(false);
	const isError = event.type === 'console.error' || event.type === 'window.error' || event.type === 'window.unhandledrejection';
	const isWarn = event.type === 'console.warn';

	const time = new Date(event.timestamp);
	const timeStr = time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });

	return (
		<div
			style={{
				...rowStyles.container,
				backgroundColor: isError ? 'rgba(255, 80, 80, 0.1)' : isWarn ? 'rgba(255, 200, 0, 0.1)' : 'transparent',
				borderLeft: `3px solid ${isError ? '#f55' : isWarn ? '#fc0' : 'transparent'}`,
			}}
		>
			<span style={rowStyles.time}>{timeStr}</span>
			<span style={{ ...rowStyles.type, color: isError ? '#f77' : isWarn ? '#fc0' : '#888' }}>
				{event.type.replace('window.', '').replace('console.', '')}
			</span>
			<span style={rowStyles.message}>
				{event.message}
				{event.stack && (
					<span
						style={rowStyles.stackIndicator}
						onClick={() => setShowStack(!showStack)}
						title="Toggle stack trace"
					>
						{showStack ? ' ▴' : ' ▾'}
					</span>
				)}
			</span>
			{showStack && event.stack && (
				<pre style={rowStyles.stack}>{event.stack}</pre>
			)}
		</div>
	);
}

