import * as React from 'react';
import { view, prop } from '@vscode/observables-react';
import type { IReader } from '@vscode/observables';
import { styles, mergeStyles } from './styles.js';
import type { ExplorerModel } from './ExplorerModel.js';
import {
  aggregateInputProperties,
  type AggregatedInputProperty,
  type FixtureInputStore,
  type IJsonSchema,
} from '../core/index.js';

/** Resolves the value shared by every fixture of a property. */
function readSharedValue(
  reader: IReader,
  store: FixtureInputStore,
  property: AggregatedInputProperty,
): { value: unknown; mixed: boolean } {
  return { value: store.readValue(reader, property.name, property.schema), mixed: false };
}

/** Short, human-readable type annotation shown next to a property name. */
function describeType(schema: IJsonSchema): string {
  if (schema.enum) { return 'enum'; }
  if (schema.type === 'integer') { return 'number'; }
  return schema.type ?? 'value';
}

/** Renders the input element appropriate for the property's JSON Schema. */
function renderControl(
  schema: IJsonSchema,
  value: unknown,
  mixed: boolean,
  setValue: (next: unknown) => void,
): React.ReactNode {
  // Enumerations → dropdown.
  if (schema.enum && schema.enum.length > 0) {
    const current = mixed ? '' : String(value ?? '');
    return (
      <select
        style={styles.propertySelect as React.CSSProperties}
        value={current}
        onChange={(e) => {
          const raw = e.target.value;
          const match = schema.enum!.find((o) => String(o) === raw);
          setValue(match);
        }}
      >
        {mixed && <option value="">— mixed —</option>}
        {schema.enum.map((option) => (
          <option key={String(option)} value={String(option)}>{String(option)}</option>
        ))}
      </select>
    );
  }

  // Booleans → checkbox (indeterminate when mixed).
  if (schema.type === 'boolean') {
    return (
      <input
        type="checkbox"
        ref={(el) => { if (el) { el.indeterminate = mixed; } }}
        checked={value === true}
        onChange={(e) => setValue(e.target.checked)}
      />
    );
  }

  // Numbers → number input.
  if (schema.type === 'number' || schema.type === 'integer') {
    return (
      <input
        type="number"
        style={styles.propertyInput as React.CSSProperties}
        value={mixed ? '' : (value === undefined || value === null ? '' : String(value))}
        placeholder={mixed ? 'mixed' : undefined}
        onChange={(e) => {
          const raw = e.target.value;
          if (raw === '') { setValue(undefined); return; }
          const parsed = schema.type === 'integer' ? parseInt(raw, 10) : parseFloat(raw);
          if (!Number.isNaN(parsed)) { setValue(parsed); }
        }}
      />
    );
  }

  // Strings (and unknown) → text input.
  if (schema.type === 'string' || schema.type === undefined) {
    return (
      <input
        type="text"
        style={styles.propertyInput as React.CSSProperties}
        value={mixed ? '' : (value === undefined || value === null ? '' : String(value))}
        placeholder={mixed ? 'mixed' : 'Enter value…'}
        onChange={(e) => setValue(e.target.value)}
      />
    );
  }

  // Fallback: edit raw JSON.
  return (
    <input
      type="text"
      style={styles.propertyInput as React.CSSProperties}
      value={mixed ? '' : (value === undefined ? '' : JSON.stringify(value))}
      placeholder={mixed ? 'mixed' : 'JSON value…'}
      onChange={(e) => {
        try {
          setValue(e.target.value === '' ? undefined : JSON.parse(e.target.value));
        } catch {
          /* keep typing until valid JSON */
        }
      }}
    />
  );
}

/** A single labelled control bound to one aggregated input property across all its fixtures. */
const PropertyControl = view(
  {
    model: prop.const<ExplorerModel>(),
    property: prop.const<AggregatedInputProperty>(),
  },
  (reader, props) => {
    const { property, model } = props;
    const { name, schema, fixtureIds } = property;
    const store = model.inputStore;
    const { value, mixed } = readSharedValue(reader, store, property);

    const setValue = (next: unknown): void => {
      store.setValue(name, schema, next);
    };

    return (
      <div style={styles.propertyRow}>
        <div style={styles.propertyLabel}>
          {name}
          <span style={{ color: 'var(--component-explorer-descriptionForeground)' }}> : {describeType(schema)}</span>
        </div>
        {renderControl(schema, value, mixed, setValue)}
        {schema.description && <div style={styles.propertyDescription}>{schema.description}</div>}
        {fixtureIds.length > 1 && (
          <div style={styles.propertyDescription}>Applies to {fixtureIds.length} rendered fixtures</div>
        )}
      </div>
    );
  }
);

/**
 * Properties panel: aggregates the input schemas of every fixture currently rendered in the
 * preview area and presents one control per shared property. Editing a control updates the
 * `input` of all fixtures that declare that property (same name + schema), so common values
 * like a theme can be switched across the whole view at once.
 */
export const RightSidebar = view(
  {
    model: prop.const<ExplorerModel>(),
  },
  (reader, props) => {
    const model = props.model;
    const fixtures = model.renderedFixtures.read(reader);
    const properties = aggregateInputProperties(
      fixtures.map((f) => ({ id: f.id, inputSchema: f.component.inputSchema })),
    ).filter(property => property.fixtureIds.some(fixtureId => {
      const fixture = fixtures.find(candidate => candidate.id === fixtureId);
      return fixture?.component.inputControls?.[property.name]?.placement !== 'toolbar';
    }));

    return (
      <div style={mergeStyles(styles.sidebar, styles.sidebarRight)}>
        <div style={styles.sidebarHeader}>
          <span style={{ marginRight: '6px', color: 'var(--component-explorer-textLink-foreground)' }}>&lt;/&gt;</span>
          Props
        </div>
        <div style={styles.sidebarContent}>
          {fixtures.length === 0 ? (
            <div style={emptyStyle}>Select a component or folder to preview</div>
          ) : properties.length === 0 ? (
            <div style={emptyStyle}>The rendered fixtures declare no configurable inputs.</div>
          ) : (
            <div style={styles.propertiesPanel}>
              {properties.map((property) => (
                <PropertyControl
                  key={`${property.name}:${property.fixtureIds.join(',')}`}
                  model={model}
                  property={property}
                />
              ))}
            </div>
          )}
        </div>
      </div>
    );
  }
);

const emptyStyle: React.CSSProperties = {
  padding: '12px',
  color: 'var(--component-explorer-descriptionForeground)',
  fontSize: '12px',
};
