import * as React from 'react';
import { observableValue, type IReader } from '@vscode/observables';
import { prop, ViewModel, viewWithModel } from '@vscode/observables-react';
import type { ConsoleEventsStore } from '../core/ConsoleEventsStore.js';
import { OUTPUT_DEBUG_PANEL_ID } from '../core/FixtureInteractionRuntime.js';
import type { ExplorerModel, FixtureItem } from './ExplorerModel.js';
import { DebugWorkbench, type DebugWorkbenchEntry } from './DebugWorkbench.js';
import { resolveDebugPanelPlacement } from './DebugPanelPlacement.js';

interface EntryCandidate extends DebugWorkbenchEntry {
  readonly typeId: string;
}

class BottomDebugPanelModel extends ViewModel({
    model: prop.const<ExplorerModel>(),
    consoleStore: prop.const<ConsoleEventsStore>(),
}) {
  readonly headerHost = observableValue<HTMLElement | null>(this, null);

  get model(): ExplorerModel { return this.props.model; }
  get consoleStore(): ConsoleEventsStore { return this.props.consoleStore; }

  setHeaderHost = (element: HTMLDivElement | null): void => {
    this.headerHost.set(element, undefined);
  };
}

export const BottomDebugPanel = viewWithModel(
  BottomDebugPanelModel,
  {},
  (reader, panelModel) => {
    const rows = panelModel.model.selectedFixtures.read(reader);
    const candidates: EntryCandidate[] = [];

    for (const row of rows) {
      if (row.type === 'single') {
        collectFixtureEntries(row.fixture, 1, panelModel.model, reader, candidates);
      } else if (row.type === 'variants') {
        for (const fixture of row.fixtures) {
          collectFixtureEntries(fixture, row.fixtures.length, panelModel.model, reader, candidates);
        }
      }
    }

    const counts = new Map<string, number>();
    for (const candidate of candidates) {
      counts.set(candidate.typeId, (counts.get(candidate.typeId) ?? 0) + 1);
    }
    const entries = candidates.map(({ typeId, ...candidate }) => ({
      ...candidate,
      title: (counts.get(typeId) ?? 0) > 1
        ? `${candidate.fixtureName}: ${candidate.title}`
        : candidate.title,
    }));
    const consoleEvents = panelModel.consoleStore.events.read(reader);
    if (entries.length === 0 && consoleEvents.length === 0) {
      return null;
    }

    const workbenchId = `bottom:${panelModel.model.selectedNodeId.read(reader) ?? 'root'}`;
    const activeEntry = panelModel.model.debugWorkbenchState.getActiveEntry(workbenchId);
    const activeEntryKey = activeEntry.read(reader);
    const contentVisible = activeEntryKey !== undefined;
    return (
      <div style={contentVisible ? styles.containerOpen : styles.containerClosed}>
        {!contentVisible && (
          <div style={styles.toolbar}>
            <div ref={panelModel.setHeaderHost} style={styles.headerHost} />
          </div>
        )}
        <div style={contentVisible ? styles.workbenchOpen : styles.workbenchClosed}>
          <DebugWorkbench
            workbenchId={workbenchId}
            entries={entries}
            activeEntryKey={activeEntryKey ?? '$console'}
            externalHeaderHost={panelModel.headerHost.read(reader)}
            contentVisible={contentVisible}
            onActiveEntryChange={entryKey => activeEntry.set(entryKey, undefined)}
            onClose={() => activeEntry.set(undefined, undefined)}
            store={panelModel.model.debugStore}
            stateStore={panelModel.model.debugWorkbenchState}
            consoleStore={panelModel.consoleStore}
            popOutHref={undefined}
            floatTopHeaders={false}
          />
        </div>
      </div>
    );
  },
);

function collectFixtureEntries(
  fixture: FixtureItem,
  logicalFixtureCount: number,
  model: ExplorerModel,
  reader: IReader,
  target: EntryCandidate[],
): void {
  for (const panel of fixture.component.debugPanels) {
    if (resolveDebugPanelPlacement(panel.placement, logicalFixtureCount) !== 'bottom-panel') continue;
    target.push({
      key: `${fixture.id}:${panel.id}`,
      typeId: panel.id,
      fixtureId: fixture.id,
      fixtureName: fixture.name,
      panelId: panel.id,
      title: panel.title,
      definition: panel,
    });
  }

  const info = model.debugStore.read(reader, fixture.id);
  if (logicalFixtureCount > 1 && info?.ready && info.hasOutput) {
    target.push({
      key: `${fixture.id}:${OUTPUT_DEBUG_PANEL_ID}`,
      typeId: OUTPUT_DEBUG_PANEL_ID,
      fixtureId: fixture.id,
      fixtureName: fixture.name,
      panelId: OUTPUT_DEBUG_PANEL_ID,
      title: 'Output',
      outputEditable: info.outputEditable,
    });
  }
}

const styles = {
  containerOpen: {
    position: 'relative',
    height: '260px',
    minHeight: '140px',
    flex: '0 0 auto',
    padding: '0 8px 8px',
    boxSizing: 'border-box',
    backgroundColor: 'var(--component-explorer-editor-background)',
  } as React.CSSProperties,
  containerClosed: {
    height: '28px',
    flex: '0 0 auto',
    padding: '0 8px',
    backgroundColor: 'var(--component-explorer-editor-background)',
  } as React.CSSProperties,
  toolbar: {
    display: 'flex',
    height: '28px',
    alignItems: 'center',
    borderTop: '1px solid var(--component-explorer-panel-border)',
  } as React.CSSProperties,
  headerHost: {
    flex: 1,
    minWidth: 0,
  } as React.CSSProperties,
  workbenchOpen: {
    height: '100%',
    minHeight: 0,
  } as React.CSSProperties,
  workbenchClosed: {
    height: 0,
    minHeight: 0,
    overflow: 'hidden',
  } as React.CSSProperties,
};
