import { autorun, observableValue, type IObservable, type IReader } from '@vscode/observables';
import type { CSSProperties, PointerEvent as ReactPointerEvent, ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { createRoot } from 'react-dom/client';
import { prop, ViewModel, viewWithModel } from '@vscode/observables-react';
import type { ConsoleEventsStore } from '../core/ConsoleEventsStore.js';
import type { DebugPanelDefinition, IDisposable } from '../core/fixtureApi.js';
import type { FixtureDebugInfo } from './FixtureDebugStore.js';
import {
  activateDebugEntry,
  dockDebugEntry,
  getVisibleDebugEntryKeys,
  reconcileDebugWorkbenchLayout,
  reorderDebugEntry,
  updateDebugSplitRatio,
  type DebugDockZone,
  type DebugSplitNode,
  type DebugStackNode,
  type DebugWorkbenchNode,
} from './DebugWorkbenchLayout.js';
import { FixtureDebugStore } from './FixtureDebugStore.js';
import { OUTPUT_DEBUG_PANEL_ID } from '../core/FixtureInteractionRuntime.js';
import { ConsolePanel } from './ConsolePanel.js';
import type { DebugWorkbenchStateStore } from './DebugWorkbenchState.js';

export interface DebugWorkbenchEntry {
  readonly key: string;
  readonly title: string;
  readonly fixtureId: string;
  readonly fixtureName: string;
  readonly panelId: string;
  readonly definition?: DebugPanelDefinition;
  readonly outputEditable?: boolean;
}

interface ConsoleWorkbenchEntry {
  readonly key: '$console';
  readonly title: 'Console';
}

type WorkbenchEntry = DebugWorkbenchEntry | ConsoleWorkbenchEntry;

export interface DebugWorkbenchProps {
  readonly workbenchId: string;
  readonly entries: readonly DebugWorkbenchEntry[];
  readonly activeEntryKey: string;
  readonly store: FixtureDebugStore;
  readonly stateStore: DebugWorkbenchStateStore;
  readonly consoleStore: ConsoleEventsStore | undefined;
  readonly onActiveEntryChange: (entryKey: string) => void;
  readonly onClose: (() => void) | undefined;
  readonly externalHeaderHost: HTMLElement | null | undefined;
  readonly contentVisible: boolean;
  readonly popOutHref?: string;
  readonly floatTopHeaders: boolean;
}

interface DropTarget {
  readonly stackId: string;
  readonly zone: DebugDockZone;
}

class DebugWorkbenchViewModel extends ViewModel({
  workbenchId: prop.const<string>(),
  entries: prop<readonly DebugWorkbenchEntry[]>(),
  activeEntryKey: prop<string>(),
  store: prop.const<FixtureDebugStore>(),
  stateStore: prop.const<DebugWorkbenchStateStore>(),
  consoleStore: prop.const<ConsoleEventsStore | undefined>(),
  onActiveEntryChange: prop.const<(entryKey: string) => void>(),
  onClose: prop.const<(() => void) | undefined>(),
  externalHeaderHost: prop<HTMLElement | null | undefined>(),
  contentVisible: prop<boolean>(),
  popOutHref: prop.const<string | undefined>(),
  floatTopHeaders: prop.const<boolean>(),
}) {
  readonly allEntries;
  readonly layout;
  readonly draggedEntryKey = observableValue<string | undefined>(this, undefined);
  readonly dropTarget = observableValue<DropTarget | undefined>(this, undefined);
  private readonly entriesByKey = new Map<string, WorkbenchEntry>();
  private rootElement: HTMLDivElement | null = null;
  private toolbarElement: HTMLDivElement | null = null;
  private stopPointerDrag: (() => void) | undefined;
  private suppressClickEntryKey: string | undefined;

  constructor(props: {
    readonly workbenchId: string;
    readonly entries: IObservable<readonly DebugWorkbenchEntry[]>;
    readonly activeEntryKey: IObservable<string>;
    readonly store: FixtureDebugStore;
    readonly stateStore: DebugWorkbenchStateStore;
    readonly consoleStore: ConsoleEventsStore | undefined;
    readonly onActiveEntryChange: (entryKey: string) => void;
    readonly onClose: (() => void) | undefined;
    readonly externalHeaderHost: IObservable<HTMLElement | null | undefined>;
    readonly contentVisible: IObservable<boolean>;
    readonly popOutHref: string | undefined;
    readonly floatTopHeaders: boolean;
  }) {
    super(props);
    const initialEntries = this.reconcileEntries(this.withConsoleEntry(props.entries.get()));
    if (initialEntries.length === 0) {
      throw new Error('DebugWorkbench requires at least one entry');
    }
    this.allEntries = observableValue<readonly WorkbenchEntry[]>(this, initialEntries);
    this.layout = props.stateStore.getLayout(
      props.workbenchId,
      initialEntries.map(entry => entry.key),
      props.activeEntryKey.get(),
    );
    this._store.add(autorun(reader => {
      const entries = this.reconcileEntries(this.withConsoleEntry(props.entries.read(reader)));
      if (entries.length === 0) {
        throw new Error('DebugWorkbench requires at least one entry');
      }
      const currentEntries = this.allEntries.get();
      if (
        entries.length !== currentEntries.length
        || entries.some((entry, index) => entry !== currentEntries[index])
      ) {
        this.allEntries.set(entries, undefined);
      }
      const entryKey = props.activeEntryKey.read(reader);
      const current = this.layout.get();
      const next = reconcileDebugWorkbenchLayout(
        current,
        entries.map(entry => entry.key),
        entryKey,
      );
      if (next !== current) this.layout.set(next, undefined);
    }));
  }

  getStackEntries(stack: DebugStackNode): readonly WorkbenchEntry[] {
    return stack.entryKeys
      .map(key => this.entriesByKey.get(key))
      .filter((entry): entry is WorkbenchEntry => entry !== undefined);
  }

  getEntry(entryKey: string): WorkbenchEntry | undefined {
    return this.entriesByKey.get(entryKey);
  }

  get store(): FixtureDebugStore { return this.props.store; }
  get consoleStore(): ConsoleEventsStore | undefined { return this.props.consoleStore; }
  get workbenchId(): string { return this.props.workbenchId; }
  get popOutHref(): string | undefined { return this.props.popOutHref; }
  get onClose(): (() => void) | undefined { return this.props.onClose; }
  get floatTopHeaders(): boolean { return this.props.floatTopHeaders; }
  get externalHeaderHost(): IObservable<HTMLElement | null | undefined> {
    return this.props.externalHeaderHost;
  }
  get contentVisible(): IObservable<boolean> { return this.props.contentVisible; }

  activate(entryKey: string): void {
    const current = this.layout.get();
    const next = activateDebugEntry(current, entryKey);
    if (next !== current) this.layout.set(next, undefined);
    this.props.onActiveEntryChange(entryKey);
  }

  open(entryKey: string, launcher: HTMLButtonElement): void {
    const origins = this.captureLauncherTabOrigins(launcher.parentElement);
    this.activate(entryKey);
    requestAnimationFrame(() => this.animateTabsFrom(origins));
  }

  finishTabDrag(): void {
    this.stopPointerDrag?.();
    this.stopPointerDrag = undefined;
    this.draggedEntryKey.set(undefined, undefined);
    this.dropTarget.set(undefined, undefined);
  }

  startTabPointerDrag(event: ReactPointerEvent<HTMLButtonElement>, entryKey: string): void {
    if (event.button !== 0) return;
    this.finishTabDrag();
    const source = event.currentTarget;
    const pointerId = event.pointerId;
    const startX = event.clientX;
    const startY = event.clientY;
    let dragging = false;
    const onMove = (pointerEvent: PointerEvent) => {
      if (!dragging && Math.hypot(pointerEvent.clientX - startX, pointerEvent.clientY - startY) < 4) {
        return;
      }
      dragging = true;
      pointerEvent.preventDefault();
      this.draggedEntryKey.set(entryKey, undefined);
      this.updatePointerDropTarget(pointerEvent.clientX, pointerEvent.clientY);
    };
    const onUp = (pointerEvent: PointerEvent) => {
      if (dragging) {
        pointerEvent.preventDefault();
        this.completePointerDrop(entryKey, pointerEvent.clientX, pointerEvent.clientY);
        this.suppressClickEntryKey = entryKey;
        setTimeout(() => {
          if (this.suppressClickEntryKey === entryKey) this.suppressClickEntryKey = undefined;
        }, 0);
      }
      this.finishTabDrag();
    };
    source.setPointerCapture(pointerId);
    source.addEventListener('pointermove', onMove);
    source.addEventListener('pointerup', onUp, { once: true });
    source.addEventListener('pointercancel', onUp, { once: true });
    this.stopPointerDrag = () => {
      source.removeEventListener('pointermove', onMove);
      source.removeEventListener('pointerup', onUp);
      source.removeEventListener('pointercancel', onUp);
      if (source.hasPointerCapture(pointerId)) source.releasePointerCapture(pointerId);
    };
  }

  consumeSuppressedClick(entryKey: string): boolean {
    if (this.suppressClickEntryKey !== entryKey) return false;
    this.suppressClickEntryKey = undefined;
    return true;
  }

  updatePaneDropTarget(stackId: string, zone: DebugDockZone): void {
    const current = this.dropTarget.get();
    if (current?.stackId === stackId && current.zone === zone) return;
    this.dropTarget.set({ stackId, zone }, undefined);
  }

  startSplitResize(
    event: ReactPointerEvent<HTMLDivElement>,
    split: DebugSplitNode,
  ): void {
    event.preventDefault();
    const container = event.currentTarget.parentElement;
    if (!container) return;
    const rect = container.getBoundingClientRect();
    const update = (pointerEvent: PointerEvent) => {
      const ratio = split.orientation === 'horizontal'
        ? (pointerEvent.clientX - rect.left) / rect.width
        : (pointerEvent.clientY - rect.top) / rect.height;
      this.layout.set(updateDebugSplitRatio(this.layout.get(), split.id, ratio), undefined);
    };
    const stop = () => {
      window.removeEventListener('pointermove', update);
      window.removeEventListener('pointerup', stop);
      window.removeEventListener('pointercancel', stop);
    };
    window.addEventListener('pointermove', update);
    window.addEventListener('pointerup', stop);
    window.addEventListener('pointercancel', stop);
  }

  setToolbarElement(element: HTMLDivElement | null): void {
    if (this.toolbarElement === element) return;
    this.toolbarElement = element;
  }

  setRootElement(element: HTMLDivElement | null): void {
    this.rootElement = element;
  }

  override dispose(): void {
    this.finishTabDrag();
    super.dispose();
  }

  private updatePointerDropTarget(clientX: number, clientY: number): void {
    const dockTarget = this.findDockTargetAt(clientX, clientY);
    if (dockTarget) {
      this.updatePaneDropTarget(
        dockTarget.dataset.debugStackId!,
        dockTarget.dataset.debugDockZone as DebugDockZone,
      );
      return;
    }
    const stack = this.findStackAt(clientX, clientY);
    if (!stack) {
      this.dropTarget.set(undefined, undefined);
      return;
    }
    this.updatePaneDropTarget(
      stack.dataset.debugStackId!,
      getDockZone(stack.getBoundingClientRect(), clientX, clientY),
    );
  }

  private completePointerDrop(entryKey: string, clientX: number, clientY: number): void {
    const targetTab = this.findTabAt(clientX, clientY);
    if (targetTab) {
      const targetEntryKey = targetTab.dataset.debugEntryKey;
      if (targetEntryKey && targetEntryKey !== entryKey) {
        const rect = targetTab.getBoundingClientRect();
        this.layout.set(reorderDebugEntry(
          this.layout.get(),
          entryKey,
          targetEntryKey,
          clientX < rect.left + rect.width / 2,
        ), undefined);
      }
      return;
    }
    const dockTarget = this.findDockTargetAt(clientX, clientY);
    const stack = this.findStackAt(clientX, clientY);
    const stackId = dockTarget?.dataset.debugStackId ?? stack?.dataset.debugStackId;
    const zone = dockTarget?.dataset.debugDockZone as DebugDockZone | undefined
      ?? (stackId === this.dropTarget.get()?.stackId ? this.dropTarget.get()?.zone : undefined)
      ?? (stack ? getDockZone(stack.getBoundingClientRect(), clientX, clientY) : 'center');
    if (!stackId) return;
    this.layout.set(dockDebugEntry(
      this.layout.get(),
      entryKey,
      stackId,
      zone,
    ), undefined);
    this.props.onActiveEntryChange(entryKey);
  }

  private findTabAt(clientX: number, clientY: number): HTMLButtonElement | undefined {
    return this.findElementAt<HTMLButtonElement>('.fixture-debug-toolbar-tab', clientX, clientY);
  }

  private findStackAt(clientX: number, clientY: number): HTMLDivElement | undefined {
    return this.findElementAt<HTMLDivElement>('.debug-workbench-stack', clientX, clientY);
  }

  private findDockTargetAt(clientX: number, clientY: number): HTMLDivElement | undefined {
    return this.findElementAt<HTMLDivElement>('.debug-workbench-dock-target', clientX, clientY)
      ?? this.findElementAt<HTMLDivElement>('.debug-workbench-drop-region', clientX, clientY);
  }

  private findElementAt<T extends HTMLElement>(
    selector: string,
    clientX: number,
    clientY: number,
  ): T | undefined {
    const root = (this.rootElement ?? this.toolbarElement)?.getRootNode();
    if (!(root instanceof Document || root instanceof ShadowRoot)) return undefined;
    return [...root.querySelectorAll<T>(selector)].find(element => {
      const owner = element.closest<HTMLElement>('[data-debug-workbench-id]');
      if (owner?.dataset.debugWorkbenchId !== this.props.workbenchId) return false;
      const rect = element.getBoundingClientRect();
      return clientX >= rect.left && clientX <= rect.right
        && clientY >= rect.top && clientY <= rect.bottom;
    });
  }

  private withConsoleEntry(entries: readonly DebugWorkbenchEntry[]): readonly WorkbenchEntry[] {
    return this.props.consoleStore
    ? [{ key: '$console', title: 'Console' }, ...entries]
    : entries;
  }

  private reconcileEntries(entries: readonly WorkbenchEntry[]): readonly WorkbenchEntry[] {
    const reconciled = entries.map(entry => {
      const current = this.entriesByKey.get(entry.key);
      return current && workbenchEntriesEqual(current, entry) ? current : entry;
    });
    this.entriesByKey.clear();
    for (const entry of reconciled) this.entriesByKey.set(entry.key, entry);
    return reconciled;
  }

  private captureLauncherTabOrigins(toolbar: HTMLElement | null): ReadonlyMap<string, DOMRect> {
    const result = new Map<string, DOMRect>();
    for (const tab of toolbar?.querySelectorAll<HTMLButtonElement>('[data-debug-entry-key]') ?? []) {
      const entryKey = tab.dataset.debugEntryKey;
      if (entryKey) result.set(entryKey, tab.getBoundingClientRect());
    }
    return result;
  }

  private animateTabsFrom(origins: ReadonlyMap<string, DOMRect>): void {
    for (const tab of this.rootElement?.querySelectorAll<HTMLButtonElement>('[data-debug-entry-key]') ?? []) {
      const origin = origins.get(tab.dataset.debugEntryKey ?? '');
      if (!origin) continue;
      const target = tab.getBoundingClientRect();
      tab.animate([
        {
          transform: `translate(${origin.left - target.left}px, ${origin.top - target.top}px)`,
          opacity: 0.6,
        },
        { transform: 'translate(0, 0)', opacity: 1 },
      ], {
        duration: 220,
        easing: 'cubic-bezier(0.2, 0, 0, 1)',
      });
    }
  }
}

function workbenchEntriesEqual(left: WorkbenchEntry, right: WorkbenchEntry): boolean {
  if (isConsoleEntry(left) || isConsoleEntry(right)) {
    return isConsoleEntry(left) && isConsoleEntry(right);
  }
  return left.key === right.key
    && left.title === right.title
    && left.fixtureId === right.fixtureId
    && left.fixtureName === right.fixtureName
    && left.panelId === right.panelId
    && left.definition === right.definition
    && left.outputEditable === right.outputEditable;
}

export const DebugWorkbench = viewWithModel(
  DebugWorkbenchViewModel,
  (reader, model) => {
    const layout = model.layout.read(reader);
    model.allEntries.read(reader);
    const contentVisible = model.contentVisible.read(reader);
    const draggedEntryKey = model.draggedEntryKey.read(reader);
    const visibleEntryKeys = contentVisible
      ? getVisibleDebugEntryKeys(layout)
      : new Set<string>();
    const externalHeaderHost = model.externalHeaderHost.read(reader);
    const launcher = (
      <div
        ref={element => model.setToolbarElement(element)}
        role="toolbar"
        aria-label="Fixture debug panels"
        className="fixture-debug-toolbar-tabs"
        data-debug-workbench-id={model.workbenchId}
        style={debugToolbarStyle}
      >
        {model.allEntries.read(reader).map(entry => (
          <button
            key={entry.key}
            type="button"
            data-debug-entry-key={entry.key}
            className="fixture-debug-toolbar-tab"
            style={debugTabStyle}
            onClick={event => model.open(entry.key, event.currentTarget)}
            title={`Show ${entry.title}`}
          >
            {entry.title}
          </button>
        ))}
        {model.popOutHref && <PopOutLink href={model.popOutHref} />}
      </div>
    );

    return (
      <div
        ref={element => model.setRootElement(element)}
        className="debug-workbench"
        data-debug-workbench-id={model.workbenchId}
        style={debugWorkbenchStyle}
      >
        {!contentVisible && externalHeaderHost && createPortal(launcher, externalHeaderHost)}
        {contentVisible && (
          <div className="debug-workbench-layout" style={layoutRootStyle}>
            {renderLayoutNode(
              model,
              layout,
              reader,
              model.floatTopHeaders,
              model.floatTopHeaders,
            )}
          </div>
        )}
      </div>
    );
  },
);

function renderLayoutNode(
  model: DebugWorkbenchViewModel,
  node: DebugWorkbenchNode,
  reader: IReader,
  topEdge: boolean,
  rightmostTopEdge: boolean,
): ReactNode {
  if (node.type === 'stack') {
    return renderStack(model, node, reader, topEdge, rightmostTopEdge);
  }
  const horizontal = node.orientation === 'horizontal';
  const firstSize = `minmax(0, ${node.ratio}fr)`;
  const secondSize = `minmax(0, ${1 - node.ratio}fr)`;
  return (
    <div
      key={node.id}
      className={`debug-workbench-split debug-workbench-split-${node.orientation}`}
      style={{
        ...splitStyle,
        gridTemplateColumns: horizontal ? `${firstSize} 6px ${secondSize}` : 'minmax(0, 1fr)',
        gridTemplateRows: horizontal ? 'minmax(0, 1fr)' : `${firstSize} 6px ${secondSize}`,
      }}
    >
      {renderLayoutNode(
        model,
        node.first,
        reader,
        topEdge,
        horizontal ? false : rightmostTopEdge,
      )}
      <div
        role="separator"
        aria-orientation={horizontal ? 'vertical' : 'horizontal'}
        className="debug-workbench-splitter"
        style={{
          ...splitterStyle,
          cursor: horizontal ? 'col-resize' : 'row-resize',
          borderLeft: horizontal ? '1px solid var(--component-explorer-panel-border)' : undefined,
          borderTop: horizontal ? undefined : '1px solid var(--component-explorer-panel-border)',
        }}
        onPointerDown={event => model.startSplitResize(event, node)}
      />
      {renderLayoutNode(
        model,
        node.second,
        reader,
        horizontal ? topEdge : false,
        horizontal ? rightmostTopEdge : false,
      )}
    </div>
  );
}

function renderStack(
  model: DebugWorkbenchViewModel,
  stack: DebugStackNode,
  reader: IReader,
  topEdge: boolean,
  rightmostTopEdge: boolean,
): ReactNode {
  const entry = model.getEntry(stack.activeEntryKey);
  if (!entry) return null;
  const dropTarget = model.dropTarget.read(reader);
  const draggedEntryKey = model.draggedEntryKey.read(reader);
  const activeDropZone = dropTarget?.stackId === stack.id ? dropTarget.zone : undefined;
  const visibleEntryKeys = getVisibleDebugEntryKeys(model.layout.get());
  return (
    <div
      key={stack.id}
      className="debug-workbench-stack"
      data-debug-stack-id={stack.id}
      data-drop-zone={activeDropZone}
      style={stackStyle}
    >
      {renderStackHeader(
        model,
        stack,
        visibleEntryKeys,
        draggedEntryKey,
        topEdge,
        rightmostTopEdge,
      )}
      <div style={stackContentStyle}>
        <DebugPanelSurface
          key={`${stack.id}:${entry.key}`}
          entry={entry}
          store={model.store}
          consoleStore={model.consoleStore}
        />
      </div>
      {draggedEntryKey && activeDropZone && renderDockOverlay(stack.id, activeDropZone)}
    </div>
  );
}

function renderStackHeader(
  model: DebugWorkbenchViewModel,
  stack: DebugStackNode,
  visibleEntryKeys: ReadonlySet<string>,
  draggedEntryKey: string | undefined,
  topEdge: boolean,
  rightmostTopEdge: boolean,
): ReactNode {
  return (
    <div
      key={stack.id}
      role="toolbar"
      aria-label="Fixture debug panels"
      className="fixture-debug-toolbar-tabs"
      style={topEdge ? topEdgeStackHeaderStyle : localStackHeaderStyle}
    >
      {model.getStackEntries(stack).map(entry => (
        <button
          key={entry.key}
          type="button"
          data-debug-entry-key={entry.key}
          aria-pressed={visibleEntryKeys.has(entry.key)}
          className="fixture-debug-toolbar-tab"
          data-visible={visibleEntryKeys.has(entry.key) ? 'true' : undefined}
          style={{
            ...debugTabStyle,
            ...(visibleEntryKeys.has(entry.key) ? visibleDebugTabStyle : undefined),
            ...(draggedEntryKey === entry.key ? draggingDebugTabStyle : undefined),
          }}
          onClick={() => {
            if (!model.consumeSuppressedClick(entry.key)) model.activate(entry.key);
          }}
          onPointerDown={event => model.startTabPointerDrag(event, entry.key)}
          title={`Show ${entry.title}`}
        >
          {entry.title}
        </button>
      ))}
      {rightmostTopEdge && (model.popOutHref || model.onClose) && (
        <div style={headerActionsStyle}>
          {model.popOutHref && <PopOutLink href={model.popOutHref} />}
          {model.onClose && <CloseButton onClick={model.onClose} />}
        </div>
      )}
    </div>
  );
}

function PopOutLink({ href }: { readonly href: string }): ReactNode {
  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      title="Open in embedded mode"
      aria-label="Open in embedded mode"
      className="debug-workbench-header-action"
      style={headerActionStyle}
    >
      <svg width="14" height="14" viewBox="0 0 16 16" fill="currentColor">
        <path d="M1.5 1H6v1H2v12h12v-4h1v4.5l-.5.5h-13l-.5-.5v-13l.5-.5zm8 0H15v5.5l-1-1V3.707L8.357 9.354l-.707-.708L13.293 3H10.5l-1-1z" />
      </svg>
    </a>
  );
}

function CloseButton({ onClick }: { readonly onClick: () => void }): ReactNode {
  return (
    <button
      type="button"
      title="Close debug panels"
      aria-label="Close debug panels"
      className="debug-workbench-header-action"
      style={headerActionButtonStyle}
      onClick={onClick}
    >
      <svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true">
        <path
          d="M4 4l8 8m0-8l-8 8"
          stroke="currentColor"
          strokeWidth="1.4"
          strokeLinecap="round"
        />
      </svg>
    </button>
  );
}

function renderDockOverlay(stackId: string, activeZone: DebugDockZone): ReactNode {
  const zones: readonly DebugDockZone[] = ['top', 'left', 'center', 'right', 'bottom'];
  return (
    <>
      <div
        data-debug-stack-id={stackId}
        data-debug-dock-zone={activeZone}
        className={`debug-workbench-drop-preview debug-workbench-drop-region debug-workbench-drop-preview-${activeZone}`}
        style={{ ...dropPreviewStyle, ...getDropPreviewPosition(activeZone) }}
      >
        <span style={dropPreviewLabelStyle}>
          {activeZone === 'center' ? 'Add to this pane' : `Dock ${activeZone}`}
        </span>
      </div>
      <div className="debug-workbench-dock-overlay" style={dockOverlayStyle}>
        {zones.map(zone => (
          <div
            key={zone}
            data-debug-stack-id={stackId}
            data-debug-dock-zone={zone}
            className="debug-workbench-dock-target"
            style={{
              ...dockTargetStyle,
              ...getDockTargetPosition(zone),
              ...(activeZone === zone ? activeDockTargetStyle : undefined),
            }}
            title={zone === 'center' ? 'Add to pane' : `Dock ${zone}`}
          >
            {getDockTargetGlyph(zone)}
          </div>
        ))}
      </div>
    </>
  );
}

interface DebugPanelSurfaceProps {
  readonly entry: WorkbenchEntry;
  readonly store: FixtureDebugStore;
  readonly consoleStore: ConsoleEventsStore | undefined;
}

class DebugPanelSurfaceViewModel extends ViewModel({
  entry: prop.const<WorkbenchEntry>(),
  store: prop.const<FixtureDebugStore>(),
  consoleStore: prop.const<ConsoleEventsStore | undefined>(),
}) {
  private host: HTMLDivElement | null = null;
  private panelDisposable: IDisposable | undefined;
  private lightDomTarget: LightDomPanelRenderTarget | undefined;
  private debugInfo: FixtureDebugInfo | undefined;

  constructor(props: DebugPanelSurfaceProps) {
    super(props);
    const entry = props.entry;
    if (!isConsoleEntry(entry)) {
      this._store.add(autorun(reader => {
        const info = props.store.read(reader, entry.fixtureId);
        const readyInfo = info?.ready ? info : undefined;
        if (readyInfo === this.debugInfo) return;
        this.debugInfo = readyInfo;
        this.mountPanel();
      }));
    }
  }

  setHost(host: HTMLDivElement | null): void {
    if (this.host === host) return;
    this.disposePanel();
    this.host = host;
    if (!host) return;

    this.lightDomTarget = createLightDomPanelRenderTarget(host, this.props.entry.key);
    this.mountPanel();
  }

  override dispose(): void {
    this.disposePanel();
    super.dispose();
  }

  private disposePanel(): void {
    disposeResource(this.panelDisposable);
    this.panelDisposable = undefined;
    this.lightDomTarget?.dispose();
    this.lightDomTarget = undefined;
  }

  private mountPanel(): void {
    disposeResource(this.panelDisposable);
    this.panelDisposable = undefined;
    const container = this.lightDomTarget?.renderContainer;
    if (!container) return;
    container.replaceChildren();

    const entry = this.props.entry;
    if (isConsoleEntry(entry)) {
      const store = this.props.consoleStore;
      if (!store) throw new Error('Console panel requires a console store');
      const root = createRoot(container);
      root.render(<ConsolePanel store={store} />);
      this.panelDisposable = { dispose: () => root.unmount() };
      return;
    }
    if (!this.debugInfo) return;
    this.panelDisposable = entry.panelId === OUTPUT_DEBUG_PANEL_ID
      ? mountOutputJsonPanel(container, this.debugInfo, entry.outputEditable === true)
      : mountCustomDebugPanel(container, entry, this.debugInfo);
  }
}

const DebugPanelSurface = viewWithModel(
  DebugPanelSurfaceViewModel,
  (_reader, model) => (
    <div
      ref={element => model.setHost(element)}
      className="debug-panel-surface"
      style={panelSurfaceStyle}
    />
  ),
);

function isConsoleEntry(entry: WorkbenchEntry): entry is ConsoleWorkbenchEntry {
  return entry.key === '$console';
}

interface LightDomPanelRenderTarget {
  readonly renderContainer: HTMLDivElement;
  dispose(): void;
}

function createLightDomPanelRenderTarget(
  surface: HTMLDivElement,
  entryKey: string,
): LightDomPanelRenderTarget {
  const rootNode = surface.getRootNode();
  const explorerHost = rootNode instanceof ShadowRoot ? rootNode.host : surface;
  const slotName = `debug-panel-${entryKey.replace(/[^a-zA-Z0-9_-]/g, '-')}-${Date.now()}`;
  const slot = document.createElement('slot');
  slot.name = slotName;
  slot.style.display = 'contents';
  surface.append(slot);

  const renderContainer = document.createElement('div');
  renderContainer.slot = slotName;
  renderContainer.className = 'component-explorer-debug-panel-content';
  Object.assign(renderContainer.style, {
    width: '100%',
    height: '100%',
    minWidth: '0',
    minHeight: '0',
    overflow: 'hidden',
    color: 'var(--vscode-foreground)',
    background: 'var(--vscode-editor-background)',
  });
  explorerHost.append(renderContainer);

  return {
    renderContainer,
    dispose: () => {
      slot.remove();
      renderContainer.remove();
    },
  };
}

function mountCustomDebugPanel(
  container: HTMLElement,
  entry: DebugWorkbenchEntry,
  info: FixtureDebugInfo,
): IDisposable {
  const definition = entry.definition;
  if (!definition) {
    throw new Error(`Debug panel entry "${entry.key}" has no definition`);
  }
  let session: ReturnType<FixtureDebugInfo['rendering']['activateDebugPanel']> | undefined;
  const view = definition._render(container, action => session?.sendAction(action));
  try {
    session = info.rendering.activateDebugPanel(entry.panelId, state => view.update(state));
  } catch (error) {
    disposeResource(view);
    throw error;
  }
  return {
    dispose: () => {
      session?.dispose();
      return view.dispose();
    },
  };
}

function mountOutputJsonPanel(
  container: HTMLElement,
  info: FixtureDebugInfo,
  editable: boolean,
): IDisposable {
  const root = createRoot(container);
  root.render(<OutputJsonPanel rendering={info.rendering} editable={editable} />);
  return { dispose: () => root.unmount() };
}

class OutputJsonPanelViewModel extends ViewModel({
  rendering: prop.const<FixtureDebugInfo['rendering']>(),
  editable: prop.const<boolean>(),
}) {
  readonly text = observableValue(this, '');
  readonly error = observableValue<string | undefined>(this, undefined);
  private readonly session;

  constructor(props: {
    readonly rendering: FixtureDebugInfo['rendering'];
    readonly editable: boolean;
  }) {
    super(props);
    this.session = props.rendering.activateDebugPanel(OUTPUT_DEBUG_PANEL_ID, output => {
      this.text.set(JSON.stringify(output, undefined, 2) ?? 'undefined', undefined);
      this.error.set(undefined, undefined);
    });
  }

  commit(): void {
    if (!this.props.editable) return;
    try {
      const value = JSON.parse(this.text.get()) as unknown;
      this.session.sendAction(value);
      this.error.set(undefined, undefined);
    } catch (error) {
      this.error.set(error instanceof Error ? error.message : String(error), undefined);
    }
  }

  get editable(): boolean { return this.props.editable; }

  override dispose(): void {
    this.session.dispose();
    super.dispose();
  }
}

const OutputJsonPanel = viewWithModel(
  OutputJsonPanelViewModel,
  (reader, model) => {
    const text = model.text.read(reader);
    const error = model.error.read(reader);
    return (
      <div style={outputJsonContainerStyle}>
        <textarea
          value={text}
          readOnly={!model.editable}
          spellCheck={false}
          aria-label="Fixture output JSON"
          style={outputJsonTextareaStyle}
          onChange={event => model.text.set(event.currentTarget.value, undefined)}
          onBlur={() => model.commit()}
          onKeyDown={event => {
            if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') model.commit();
          }}
        />
        {error && <div style={outputJsonErrorStyle}>{error}</div>}
      </div>
    );
  },
);

function getDropPreviewPosition(zone: DebugDockZone): CSSProperties {
  switch (zone) {
    case 'left': return { inset: '4px 50% 4px 4px' };
    case 'right': return { inset: '4px 4px 4px 50%' };
    case 'top': return { inset: '4px 4px 50% 4px' };
    case 'bottom': return { inset: '50% 4px 4px 4px' };
    case 'center': return { inset: '18%' };
  }
}

function getDockZone(rect: DOMRect, clientX: number, clientY: number): DebugDockZone {
  const x = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
  const y = Math.max(0, Math.min(1, (clientY - rect.top) / rect.height));
  const edge = 0.25;
  const candidates: { readonly zone: DebugDockZone; readonly distance: number }[] = [];
  if (x < edge) candidates.push({ zone: 'left', distance: x });
  if (x > 1 - edge) candidates.push({ zone: 'right', distance: 1 - x });
  if (y < edge) candidates.push({ zone: 'top', distance: y });
  if (y > 1 - edge) candidates.push({ zone: 'bottom', distance: 1 - y });
  candidates.sort((a, b) => a.distance - b.distance);
  return candidates[0]?.zone ?? 'center';
}

function getDockTargetPosition(zone: DebugDockZone): CSSProperties {
  switch (zone) {
    case 'top': return { left: '36px', top: 0 };
    case 'left': return { left: 0, top: '36px' };
    case 'center': return { left: '36px', top: '36px' };
    case 'right': return { left: '72px', top: '36px' };
    case 'bottom': return { left: '36px', top: '72px' };
  }
}

function getDockTargetGlyph(zone: DebugDockZone): ReactNode {
  return (
    <span
      style={{
        width: '15px',
        height: '15px',
        border: '1px solid currentColor',
        borderRadius: '2px',
        background: getDockTargetGlyphBackground(zone),
      }}
    />
  );
}

function getDockTargetGlyphBackground(zone: DebugDockZone): string {
  const color = 'color-mix(in srgb, var(--component-explorer-focusBorder) 55%, transparent)';
  switch (zone) {
    case 'top': return `linear-gradient(to bottom, ${color} 50%, transparent 50%)`;
    case 'left': return `linear-gradient(to right, ${color} 50%, transparent 50%)`;
    case 'center': return color;
    case 'right': return `linear-gradient(to left, ${color} 50%, transparent 50%)`;
    case 'bottom': return `linear-gradient(to top, ${color} 50%, transparent 50%)`;
  }
}

function disposeResource(resource: IDisposable | undefined): void {
  const result = resource?.dispose();
  if (result instanceof Promise) {
    result.catch(error => console.error('Failed to dispose debug panel', error));
  }
}

