import type { IJsonSchema } from './fixtureApi.js';

/**
 * A single input property shared by one or more of the currently rendered fixtures.
 * Properties are grouped by name **and** structural schema equality, so a control can edit
 * every fixture that declares the same property at once.
 */
export interface AggregatedInputProperty {
    readonly name: string;
    readonly schema: IJsonSchema;
    /** Ids of the fixtures that declare this exact property (same name + schema). */
    readonly fixtureIds: readonly string[];
}

/** Minimal shape needed to aggregate: a fixture id and its (merged) input schema. */
export interface ComponentInputInfo {
    readonly id: string;
    readonly inputSchema?: IJsonSchema;
}

/** Deterministic stringify (object keys sorted) for structural schema equality. */
function stableStringify(value: unknown): string {
    if (value === null || typeof value !== 'object') {
        return JSON.stringify(value) ?? 'null';
    }
    if (Array.isArray(value)) {
        return `[${value.map(stableStringify).join(',')}]`;
    }
    const entries = Object.entries(value as Record<string, unknown>)
        .filter(([, v]) => v !== undefined)
        .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
    return `{${entries.map(([k, v]) => `${JSON.stringify(k)}:${stableStringify(v)}`).join(',')}}`;
}

/**
 * Stable identity of an input property: its name plus structural schema. Two fixtures that
 * declare the same property (same name + schema) share this key, so a chosen value can be
 * persisted once and reused across every fixture that has it.
 */
export function inputPropertyKey(name: string, schema: IJsonSchema): string {
    return `${name}\u0000${stableStringify(schema)}`;
}

/**
 * Collects the input properties declared across the given fixtures, grouping identical
 * (name + schema) properties so they can be edited together. Order follows first appearance.
 */
export function aggregateInputProperties(
    components: readonly ComponentInputInfo[],
): AggregatedInputProperty[] {
    const groups = new Map<string, { name: string; schema: IJsonSchema; fixtureIds: string[] }>();
    const order: string[] = [];

    for (const component of components) {
        const properties = component.inputSchema?.properties;
        if (!properties) { continue; }
        for (const [name, schema] of Object.entries(properties)) {
            if (!schema || typeof schema !== 'object') { continue; }
            const key = inputPropertyKey(name, schema);
            let group = groups.get(key);
            if (!group) {
                group = { name, schema, fixtureIds: [] };
                groups.set(key, group);
                order.push(key);
            }
            if (!group.fixtureIds.includes(component.id)) {
                group.fixtureIds.push(component.id);
            }
        }
    }

    return order.map((key) => {
        const g = groups.get(key)!;
        return { name: g.name, schema: g.schema, fixtureIds: g.fixtureIds };
    });
}

/** The value currently in effect for a property: explicit override, else schema default. */
export function effectiveInputValue(
    override: Record<string, unknown> | undefined,
    name: string,
    schema: IJsonSchema,
): unknown {
    if (override && Object.prototype.hasOwnProperty.call(override, name)) {
        return override[name];
    }
    return schema.default;
}
