/**
 * Fixture API Consumer
 * 
 * This module validates and consumes fixture exports created by fixtureApi.
 * It provides type guards and parsing functions for cross-version compatibility.
 * 
 * The viewer imports this module to parse fixtures; projects never need this.
 */

import {
  singleFixtureBrand,
  fixtureGroupBrand,
  fixtureVariantsBrand,
  type FixtureExport,
  type SingleFixtureExport,
  type FixtureGroupExport,
  type FixtureVariantsExport,
  type DisplayMode,
  type StyleDefinition,
  type RenderReturn,
  type RenderContext,
  type IJsonSchema,
  type DebugPanelDefinition,
  type FixtureInputControlOptions,
} from './fixtureApi.js';

// ============================================================================
// Type guards (use these for runtime checks)
// Cross-version compatible thanks to Symbol.for() in fixtureApi.ts
// ============================================================================

/**
 * Type guard for SingleFixtureExport.
 * Uses the global symbol brand for cross-version compatibility.
 */
export function isSingleFixture(value: unknown): value is SingleFixtureExport {
  return (
    typeof value === 'object' &&
    value !== null &&
    singleFixtureBrand in value &&
    (value as Record<symbol, unknown>)[singleFixtureBrand] === true &&
    '_options' in value &&
    typeof (value as { _options: unknown })._options === 'object'
  );
}

/**
 * Type guard for FixtureGroupExport.
 * Uses the global symbol brand for cross-version compatibility.
 */
export function isFixtureGroup(value: unknown): value is FixtureGroupExport {
  return (
    typeof value === 'object' &&
    value !== null &&
    fixtureGroupBrand in value &&
    (value as Record<symbol, unknown>)[fixtureGroupBrand] === true &&
    '_entries' in value &&
    typeof (value as { _entries: unknown })._entries === 'object'
  );
}

/**
 * Type guard for FixtureVariantsExport.
 * Uses the global symbol brand for cross-version compatibility.
 */
export function isFixtureVariants(value: unknown): value is FixtureVariantsExport {
  return (
    typeof value === 'object' &&
    value !== null &&
    fixtureVariantsBrand in value &&
    (value as Record<symbol, unknown>)[fixtureVariantsBrand] === true &&
    '_variants' in value &&
    typeof (value as { _variants: unknown })._variants === 'object'
  );
}

/**
 * Type guard for any fixture export type.
 */
export function isFixtureExport(value: unknown): value is FixtureExport {
  return isSingleFixture(value) || isFixtureGroup(value) || isFixtureVariants(value);
}

// ============================================================================
// Parsing functions (validate and cast)
// ============================================================================

export type ParseResult<T> =
  | { success: true; data: T }
  | { success: false; error: string };

/**
 * Parses and validates a potential fixture export.
 * Returns a ParseResult with either the validated data or an error message.
 */
export function parseFixtureExport(value: unknown): ParseResult<FixtureExport> {
  if (isSingleFixture(value)) {
    return { success: true, data: value };
  }
  if (isFixtureGroup(value)) {
    return { success: true, data: value };
  }
  if (isFixtureVariants(value)) {
    return { success: true, data: value };
  }
  return { success: false, error: 'Value is not a valid fixture export (missing brand symbol or _options/_entries/_variants)' };
}

/**
 * Parses and validates a single fixture export.
 */
export function parseSingleFixture(value: unknown): ParseResult<SingleFixtureExport> {
  if (isSingleFixture(value)) {
    return { success: true, data: value };
  }
  return { success: false, error: 'Value is not a SingleFixtureExport' };
}

/**
 * Parses and validates a fixture group export.
 */
export function parseFixtureGroup(value: unknown): ParseResult<FixtureGroupExport> {
  if (isFixtureGroup(value)) {
    return { success: true, data: value };
  }
  return { success: false, error: 'Value is not a FixtureGroupExport' };
}

/**
 * Parses and validates a fixture variants export.
 */
export function parseFixtureVariants(value: unknown): ParseResult<FixtureVariantsExport> {
  if (isFixtureVariants(value)) {
    return { success: true, data: value };
  }
  return { success: false, error: 'Value is not a FixtureVariantsExport' };
}

// ============================================================================
// ComponentDefinition creation (moved from defineFixture.ts)
// ============================================================================

/**
 * Definition of a component fixture (internal representation).
 */
export interface ComponentDefinition {
  /** Unique identifier within the fixture file */
  readonly id: string;

  /** Display name shown in the tree */
  readonly name: string;

  /** Optional description for documentation */
  readonly description?: string;

  /** How to isolate this component from other components */
  readonly isolation: 'none' | 'shadow-dom' | 'iframe';

  /** How to display: page (device viewport) or component (natural size) */
  readonly displayMode: DisplayMode;

  /** Stylesheets to inject (into document head, shadow root, or iframe head depending on isolation mode) */
  readonly styles?: readonly StyleDefinition[];

  /** Background pattern for the preview canvas: 'light' (default) or 'dark' for dark transparent pattern */
  readonly background: 'light' | 'dark';

  /** Labels for categorization and filtering */
  readonly labels: readonly string[];

  /** Accumulated expected visual descriptions (from self + parent groups/variants) */
  readonly expectedVisualDescriptions: readonly string[];

  /** JSON Schema describing the expected shape of `RenderContext.input` (always an object). */
  readonly inputSchema?: IJsonSchema;

  /** Explorer presentation metadata for input properties. */
  readonly inputControls?: Readonly<Record<string, FixtureInputControlOptions>>;

  /** Statically declared custom debug panels. */
  readonly debugPanels: readonly DebugPanelDefinition<unknown, unknown>[];

  /** Source file path this fixture was defined in */
  readonly sourceFile: string;

  /**
   * Render the component into the container.
   * Returns an optional RenderResult or Promise for cleanup and async readiness.
   */
  render(container: HTMLElement, context: RenderContext): RenderReturn;
}

/**
 * Creates the component definition from a validated SingleFixtureExport.
 *
 * @param inheritedInputSchema - JSON Schema accumulated from enclosing groups/variants; merged
 *   with the fixture's own schema (the fixture's properties win on conflict).
 */
export function createComponentDefinition(
  fixture: SingleFixtureExport,
  id: string,
  name: string,
  sourceFile: string,
  inheritedVisualDescriptions: readonly string[] = [],
  inheritedInputSchema: IJsonSchema | undefined = undefined,
): ComponentDefinition {
  const options = fixture._options;
  const ownDescriptions = options.expectedVisualDescriptions
    ? (typeof options.expectedVisualDescriptions === 'string' ? [options.expectedVisualDescriptions] : [...options.expectedVisualDescriptions])
    : [];
  const expectedVisualDescriptions = [...inheritedVisualDescriptions, ...ownDescriptions];
  return {
    id,
    name,
    description: options.description,
    isolation: options.isolation ?? 'none',
    displayMode: options.displayMode ?? { type: 'component' },
    styles: options.styles,
    background: options.background ?? 'light',
    labels: options.labels ?? [],
    expectedVisualDescriptions,
    inputSchema: mergeInputSchemas(inheritedInputSchema, fixture._inputSchemaJson),
    inputControls: options.inputControls as Readonly<Record<string, FixtureInputControlOptions>> | undefined,
    debugPanels: options.debugPanels ?? [],
    sourceFile,
    render: options.render,
  };
}

/**
 * Merges two object JSON Schemas. `child` properties win over `parent` on key conflicts;
 * `required` is the de-duplicated union. Returns whichever side is defined when only one is.
 */
export function mergeInputSchemas(
  parent: IJsonSchema | undefined,
  child: IJsonSchema | undefined,
): IJsonSchema | undefined {
  if (!parent) { return child; }
  if (!child) { return parent; }
  const properties = { ...(parent.properties ?? {}), ...(child.properties ?? {}) };
  const required = [...new Set<string>([...(parent.required ?? []), ...(child.required ?? [])])];
  return {
    ...parent,
    ...child,
    type: 'object',
    properties,
    ...(required.length ? { required } : {}),
  };
}

/**
 * Builds the effective `input` object passed to a fixture: the schema's top-level property
 * defaults, overlaid with any caller-provided overrides. Returns the override unchanged when
 * there is no schema (so schemaless fixtures keep their original `undefined`/passthrough input).
 */
export function applyInputDefaults(schema: IJsonSchema | undefined, input: unknown): unknown {
  const overrides = (input && typeof input === 'object' && !Array.isArray(input))
    ? (input as Record<string, unknown>)
    : undefined;
  if (!schema?.properties) {
    return input;
  }
  const result: Record<string, unknown> = {};
  for (const [key, prop] of Object.entries(schema.properties)) {
    if (prop && typeof prop === 'object' && prop.default !== undefined) {
      result[key] = prop.default;
    }
  }
  if (overrides) {
    Object.assign(result, overrides);
  }
  return result;
}

/**
 * Type guard for checking if a value is a ComponentDefinition.
 * @deprecated Use isSingleFixture or isFixtureGroup instead
 */
export function isComponentDefinition(value: unknown): value is ComponentDefinition {
  return (
    typeof value === 'object' &&
    value !== null &&
    'render' in value &&
    typeof (value as ComponentDefinition).render === 'function' &&
    'id' in value &&
    'name' in value
  );
}
