import * as React from 'react';
import { observableValue, autorun, type IDisposable, type IReader } from '@vscode/observables';
import { viewWithModel, ViewModel, prop } from '@vscode/observables-react';
import { buildExplorerUrl } from '@vscode/component-explorer-common';
import { resolveViewport } from '../core/index.js';
import { ComponentRendering } from '../core/ComponentRenderer.js';
import type { FixtureInputStore } from '../core/index.js';
import type { ExceptionError } from '../core/ErrorInfo.js';
import type { FixtureItem } from './ExplorerModel.js';
import { buildQueryParamUrl } from '../lib/queryParamObservable.js';
import { getExplorerShadowHost } from '../lib/explorerShadowHost.js';
import { registerFixtureContainer } from '../lib/fixtureFocusTrap.js';
import {
  calculatePagePreviewGeometry,
  type FixtureViewportStore,
  type PagePreviewGeometry,
  type PagePreviewMode,
  type PageViewportSettings,
} from './PageViewportState.js';
import type { FixtureDebugStore } from './FixtureDebugStore.js';
import { DebugWorkbench, type DebugWorkbenchEntry } from './DebugWorkbench.js';
import type { DebugWorkbenchStateStore } from './DebugWorkbenchState.js';
import { resolveDebugPanelPlacement } from './DebugPanelPlacement.js';
import { OUTPUT_DEBUG_PANEL_ID } from '../core/FixtureInteractionRuntime.js';

function buildEmbeddedUrl(fixtureId: string): string {
  return buildExplorerUrl({
    pathname: location.pathname,
    baseQuery: location.search,
    mode: 'embedded',
    fixtureId,
  });
}

let _nextSlotId = 0;

class FixturePreviewItemModel extends ViewModel({
  fixture: prop.const<FixtureItem>(),
  compact: prop.const<boolean | undefined>(),
  onSelect: prop.const<((nodeId: string) => void) | undefined>(),
  inputStore: prop.const<FixtureInputStore | undefined>(),
  viewportStore: prop.const<FixtureViewportStore>(),
  availablePageHeight: prop<number>(),
  debugStore: prop.const<FixtureDebugStore>(),
  debugWorkbenchState: prop.const<DebugWorkbenchStateStore>(),
  logicalFixtureCount: prop.const<number>(),
}) {
  private _canvasRef: HTMLDivElement | null = null;
  private _fixtureContainer: HTMLDivElement | null = null;
  private _rendering: ComponentRendering | null = null;
  private _resizeObserver: ResizeObserver | null = null;
  private _pageHostResizeObserver: ResizeObserver | null = null;
  private _pageHostRef: HTMLDivElement | null = null;
  private _contentHostRef: HTMLDivElement | null = null;
  private _contentHostResizeObserver: ResizeObserver | null = null;
  private _fixtureColumnRef: HTMLDivElement | null = null;
  private _fixtureColumnResizeObserver: ResizeObserver | null = null;
  private _debugHeaderHostRef: HTMLDivElement | null = null;
  private _stopDebugPaneResize: (() => void) | undefined;
  private _mountSub: IDisposable | null = null;

  readonly measuredWidth = observableValue<number | undefined>(this, undefined);
  readonly measuredHeight = observableValue<number | undefined>(this, undefined);
  readonly availableWidth = observableValue(this, 0);
  readonly reservedHeight = observableValue(this, 0);
  readonly contentHostWidth = observableValue(this, 0);
  readonly fixtureColumnHeight = observableValue(this, 0);
  readonly debugHeaderHost = observableValue<HTMLElement | null>(this, null);
  readonly debugPaneFraction = observableValue(this, 0.4);
  readonly error = observableValue<ExceptionError | undefined>(this, undefined);
  readonly slotName = `fixture-${_nextSlotId++}`;

  get fixture(): FixtureItem { return this.props.fixture; }
  get compact(): boolean { return this.props.compact ?? false; }
  get onSelect(): ((nodeId: string) => void) | undefined { return this.props.onSelect; }
  get viewportStore(): FixtureViewportStore { return this.props.viewportStore; }
  get availablePageHeight() { return this.props.availablePageHeight; }
  get debugStore(): FixtureDebugStore { return this.props.debugStore; }
  get debugWorkbenchState(): DebugWorkbenchStateStore { return this.props.debugWorkbenchState; }
  get logicalFixtureCount(): number { return this.props.logicalFixtureCount; }
  get inputStore(): FixtureInputStore | undefined { return this.props.inputStore; }

  setContentHostRef = (el: HTMLDivElement | null): void => {
    this._contentHostResizeObserver?.disconnect();
    this._contentHostResizeObserver = null;
    this._contentHostRef = el;
    if (!el) return;
    this._contentHostResizeObserver = new ResizeObserver(() => {
      this.contentHostWidth.set(el.clientWidth, undefined);
    });
    this._contentHostResizeObserver.observe(el);
    this.contentHostWidth.set(el.clientWidth, undefined);
  };

  setFixtureColumnRef = (el: HTMLDivElement | null): void => {
    this._fixtureColumnResizeObserver?.disconnect();
    this._fixtureColumnResizeObserver = null;
    this._fixtureColumnRef = el;
    if (!el) {
      this.fixtureColumnHeight.set(0, undefined);
      return;
    }
    const measure = (): void => {
      this.fixtureColumnHeight.set(Math.ceil(el.getBoundingClientRect().height), undefined);
    };
    this._fixtureColumnResizeObserver = new ResizeObserver(measure);
    this._fixtureColumnResizeObserver.observe(el);
    measure();
  };

  selectDebugEntry = (entryKey: string): void => {
    const activeEntry = this.debugWorkbenchState.getActiveEntry(`inline:${this.fixture.id}`);
    activeEntry.set(entryKey, undefined);
  };

  closeDebugPane = (): void => {
    this.debugWorkbenchState.getActiveEntry(`inline:${this.fixture.id}`).set(undefined, undefined);
  };

  setDebugHeaderHostRef = (el: HTMLDivElement | null): void => {
    this._debugHeaderHostRef = el;
    this.debugHeaderHost.set(el, undefined);
  };

  beginDebugPaneResize(clientX: number): void {
    const host = this._contentHostRef;
    if (!host) return;
    this._stopDebugPaneResize?.();
    const onMove = (event: PointerEvent): void => {
      const rect = host.getBoundingClientRect();
      const splitterWidth = 8;
      const usableWidth = Math.max(1, rect.width - splitterWidth);
      const paneWidth = rect.right - event.clientX;
      const minPaneWidth = Math.min(280, usableWidth * 0.45);
      const minFixtureWidth = Math.min(320, usableWidth * 0.5);
      const maxPaneWidth = Math.max(minPaneWidth, usableWidth - minFixtureWidth);
      const clampedPaneWidth = Math.min(maxPaneWidth, Math.max(minPaneWidth, paneWidth));
      this.debugPaneFraction.set(clampedPaneWidth / usableWidth, undefined);
    };
    const stop = (): void => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', stop);
      window.removeEventListener('pointercancel', stop);
      document.documentElement.style.cursor = '';
      document.documentElement.style.userSelect = '';
      this._stopDebugPaneResize = undefined;
    };
    this._stopDebugPaneResize = stop;
    document.documentElement.style.cursor = 'col-resize';
    document.documentElement.style.userSelect = 'none';
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', stop);
    window.addEventListener('pointercancel', stop);
    onMove(new PointerEvent('pointermove', { clientX }));
  }

  setPageHostRef = (el: HTMLDivElement | null): void => {
    this._pageHostResizeObserver?.disconnect();
    this._pageHostResizeObserver = null;
    window.removeEventListener('resize', this._measurePageHost);
    this._pageHostRef = el;
    if (!el) return;

    this._pageHostResizeObserver = new ResizeObserver(this._measurePageHost);
    this._pageHostResizeObserver.observe(el);
    window.addEventListener('resize', this._measurePageHost);
    requestAnimationFrame(this._measurePageHost);
  };

  setCanvasRef = (el: HTMLDivElement | null): void => {
    if (el === this._canvasRef) return;

    this._cleanup();

    this._canvasRef = el;
    if (!el) return;

    // (Re)build the fixture whenever its input overrides change. A full rebuild (rather than
    // an in-place update) keeps this simple and avoids re-`attachShadow` on shadow-dom fixtures.
    this._mountSub = autorun((reader) => {
      const input = this.props.inputStore?.getInput(this.fixture.id, this.fixture.component.inputSchema).read(reader);
      if (this._rendering?.updateInput(input)) {
        return;
      }
      this._mount(input);
    });
  };

  private _mount(input: unknown): void {
    this._teardownRendering();

    const shadowHost = getExplorerShadowHost();

    const fixtureContainer = document.createElement('div');
    fixtureContainer.slot = this.slotName;

    const component = this.fixture.component;
    const displayMode = component.displayMode;
    if (displayMode.type === 'page') {
      fixtureContainer.style.width = '100%';
      fixtureContainer.style.height = '100%';
      fixtureContainer.style.boxSizing = 'border-box';
      fixtureContainer.style.overflow = 'auto';
    } else {
      fixtureContainer.style.all = 'initial';
      fixtureContainer.style.display = 'inline-block';
    }

    shadowHost.appendChild(fixtureContainer);
    this._fixtureContainer = fixtureContainer;
    registerFixtureContainer(fixtureContainer);

    const rendering = new ComponentRendering(
      fixtureContainer,
      component,
      { kind: 'explorer-ui', interactive: true },
      input,
    );
    this._rendering = rendering;
    this.debugStore.setRendering(this.fixture, rendering);
    if (displayMode.type === 'page') {
      rendering.renderTarget.style.width = '100%';
      rendering.renderTarget.style.height = '100%';
      rendering.renderTarget.style.boxSizing = 'border-box';
    }

    rendering.waitForRendering().then(() => {
      this.debugStore.markReady(this.fixture, rendering);
    }).catch((err) => {
      this.error.set(err as ExceptionError, undefined);
    });

    this._resizeObserver = new ResizeObserver((entries) => {
      for (const entry of entries) {
        const { width, height } = entry.contentRect;
        if (height > 0) {
          this.measuredWidth.set(Math.round(width), undefined);
          this.measuredHeight.set(Math.round(height), undefined);
        }
      }
    });
    this._resizeObserver.observe(rendering.renderTarget);
  }

  /** Tears down the live rendering + its DOM, leaving the autorun subscription intact. */
  private _teardownRendering(): void {
    // Fire-and-forget — UI dispose errors are not surfaced (no report consumer).
    const rendering = this._rendering;
    if (rendering) {
      this.debugStore.remove(this.fixture.id, rendering);
      rendering.dispose().catch(error => console.error('Failed to dispose fixture rendering', error));
    }
    this._rendering = null;
    this._resizeObserver?.disconnect();
    this._resizeObserver = null;
    this._fixtureContainer?.remove();
    this._fixtureContainer = null;
    this.error.set(undefined, undefined);
  }

  private _cleanup(): void {
    this._mountSub?.dispose();
    this._mountSub = null;
    this._teardownRendering();
  }

  private _measurePageHost = (): void => {
    const host = this._pageHostRef;
    const canvas = host?.firstElementChild;
    if (!host || !(canvas instanceof HTMLElement)) return;

    const canvasStyle = getComputedStyle(canvas);
    const horizontalPadding = Number.parseFloat(canvasStyle.paddingLeft)
      + Number.parseFloat(canvasStyle.paddingRight);
    this.availableWidth.set(
      Math.max(0, Math.floor(host.clientWidth - horizontalPadding)),
      undefined,
    );

    const row = host.closest<HTMLElement>('[data-row-id]');
    if (row) {
      const verticalPadding = Number.parseFloat(canvasStyle.paddingTop)
        + Number.parseFloat(canvasStyle.paddingBottom);
      const chromeHeight = host.getBoundingClientRect().top - row.getBoundingClientRect().top;
      this.reservedHeight.set(Math.max(0, Math.ceil(chromeHeight + verticalPadding)), undefined);
    }
  };

  dispose(): void {
    this._cleanup();
    this._pageHostResizeObserver?.disconnect();
    this._pageHostResizeObserver = null;
    window.removeEventListener('resize', this._measurePageHost);
    this._pageHostRef = null;
    this._contentHostResizeObserver?.disconnect();
    this._contentHostResizeObserver = null;
    this._contentHostRef = null;
    this._fixtureColumnResizeObserver?.disconnect();
    this._fixtureColumnResizeObserver = null;
    this._fixtureColumnRef = null;
    this._debugHeaderHostRef = null;
    this._stopDebugPaneResize?.();
  }
}

export const FixturePreviewItem = viewWithModel(
  FixturePreviewItemModel,
  {},
  (reader, model) => {
    const fixture = model.fixture;
    const component = fixture.component;
    const measuredWidth = model.measuredWidth.read(reader);
    const measuredHeight = model.measuredHeight.read(reader);
    const error = model.error.read(reader);
    const compact = model.compact;
    const displayMode = component.displayMode;
    const pageSettings = displayMode.type === 'page'
      ? model.viewportStore.read(reader, fixture.id, displayMode)
      : undefined;
    const pageGeometry = pageSettings
      ? calculatePagePreviewGeometry(
        pageSettings,
        model.availableWidth.read(reader),
        Math.max(0, model.availablePageHeight.read(reader) - model.reservedHeight.read(reader)),
      )
      : undefined;

    const dimensionsText = measuredWidth && measuredHeight
      ? `${measuredWidth} × ${measuredHeight}`
      : '';

    const wrapperStyle = compact ? previewItemStyles.wrapperCompact : previewItemStyles.wrapper;
    const nameStyle = compact ? previewItemStyles.nameCompact : previewItemStyles.name;
    const debugInfo = model.debugStore.read(reader, fixture.id);
    const debugEntries = getInlineDebugEntries(
      fixture,
      model.logicalFixtureCount,
      debugInfo?.ready === true && debugInfo.hasOutput,
      debugInfo?.outputEditable === true,
    );
    const activeDebugEntryKey = model.debugWorkbenchState
      .getActiveEntry(`inline:${fixture.id}`)
      .read(reader);
    const debugPaneOpen = activeDebugEntryKey !== undefined;
    const contentHostWidth = model.contentHostWidth.read(reader);
    const fixtureColumnHeight = model.fixtureColumnHeight.read(reader);
    const usableDebugWidth = Math.max(0, contentHostWidth - 8);
    const debugPaneWidth = Math.round(usableDebugWidth * model.debugPaneFraction.read(reader));
    const collapsedFixtureWidth = pageGeometry && pageSettings
      ? pageSettings.mode === 'actual'
        ? pageGeometry.visualWidth + 24
        : undefined
      : measuredWidth !== undefined
        ? measuredWidth + 24
        : undefined;
    const fixtureColumnWidth = contentHostWidth > 0
      ? debugPaneOpen
        ? Math.max(0, contentHostWidth - 8 - debugPaneWidth)
        : collapsedFixtureWidth === undefined
          ? undefined
          : Math.min(contentHostWidth, collapsedFixtureWidth)
      : undefined;
    const fallbackDebugHeight = pageGeometry
      ? Math.max(280, pageGeometry.visualHeight + 24)
      : Math.max(280, measuredHeight ?? 0);
    const debugHeight = fixtureColumnHeight > 0 ? fixtureColumnHeight : fallbackDebugHeight;
    const tabPanelId = `${model.slotName}-debug-tabpanel`;

    return (
      <div style={wrapperStyle}>
        <div style={getLabelRowStyle(debugEntries.length > 0, debugPaneOpen, fixtureColumnWidth, contentHostWidth)}>
          {compact && (
            <a
              href={buildQueryParamUrl('fixture', fixture.id)}
              style={{ ...nameStyle, textDecoration: 'none', color: 'inherit' }}
              onClick={(e) => { if (model.onSelect) { e.preventDefault(); model.onSelect(fixture.id); } }}
            >{fixture.name}</a>
          )}
          {!compact && displayMode.type !== 'page' && dimensionsText && (
            <span style={previewItemStyles.dimensions}>{dimensionsText}</span>
          )}
          {displayMode.type === 'page' && pageSettings && pageGeometry && (
            <PageViewportControls
              fixtureId={fixture.id}
              pageMode={displayMode}
              settings={pageSettings}
              geometry={pageGeometry}
              store={model.viewportStore}
            />
          )}
          {renderToolbarInputControls(reader, model)}
          {debugEntries.length > 0 && (
            <div style={previewItemStyles.debugToolbarGroup}>
              <div
                ref={model.setDebugHeaderHostRef}
                className="component-explorer-debug-header-host"
                style={previewItemStyles.debugHeaderHost}
              />
            </div>
          )}
          {debugEntries.length === 0 && (
            <a
              href={buildEmbeddedUrl(fixture.id)}
              target="_blank"
              rel="noopener noreferrer"
              title="Open in embedded mode"
              style={previewItemStyles.embeddedLink}
            >
              <EmbeddedIcon />
            </a>
          )}
        </div>
        <div
          ref={debugEntries.length > 0 ? model.setContentHostRef : undefined}
          style={debugEntries.length > 0
            ? previewItemStyles.contentWithDebug
            : undefined}
        >
          <div
            style={debugEntries.length > 0
              ? getDebugContentStyle(debugPaneOpen, fixtureColumnWidth, debugPaneWidth)
              : undefined}
          >
            <div
              ref={debugEntries.length > 0 ? model.setFixtureColumnRef : undefined}
              style={debugEntries.length > 0 ? previewItemStyles.fixtureColumn : undefined}
            >
              {pageGeometry && pageSettings ? (
                <div ref={model.setPageHostRef} style={previewItemStyles.pageHost}>
                  <div ref={model.setCanvasRef} style={getCanvasStyle(component.background, pageSettings.mode)}>
                    <div style={getPageFrameStyle(pageGeometry, pageSettings.mode)}>
                      <div style={getPageScaleLayerStyle(pageGeometry, pageSettings.mode)}>
                        <slot name={model.slotName} />
                      </div>
                    </div>
                  </div>
                </div>
              ) : (
                <div ref={model.setCanvasRef} style={getCanvasStyle(component.background, undefined)}>
                  <slot name={model.slotName} />
                </div>
              )}
              {error && <FixtureError error={error} />}
            </div>
            {debugEntries.length > 0 && (
              <>
                {debugPaneOpen && (
                  <div
                    role="separator"
                    aria-label="Resize fixture and debug panes"
                    aria-orientation="vertical"
                    style={{ ...previewItemStyles.debugSplitter, height: debugHeight }}
                    onPointerDown={event => {
                      event.preventDefault();
                      model.beginDebugPaneResize(event.clientX);
                    }}
                  />
                )}
                <div
                  id={tabPanelId}
                  role="region"
                  aria-label={`${fixture.name} debug panels`}
                  className="component-explorer-inline-debug-pane"
                  style={{
                    ...previewItemStyles.inlineDebug,
                    height: debugHeight,
                    display: debugPaneOpen ? 'block' : 'none',
                  }}
                >
                  <DebugWorkbench
                    workbenchId={`inline:${fixture.id}`}
                    entries={debugEntries}
                    activeEntryKey={activeDebugEntryKey ?? debugEntries[0].key}
                    externalHeaderHost={model.debugHeaderHost.read(reader)}
                    contentVisible={debugPaneOpen}
                    onActiveEntryChange={model.selectDebugEntry}
                    onClose={model.closeDebugPane}
                    store={model.debugStore}
                    stateStore={model.debugWorkbenchState}
                    consoleStore={undefined}
                    popOutHref={buildEmbeddedUrl(fixture.id)}
                    floatTopHeaders
                  />
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    );

    function getInlineDebugEntries(
      fixture: FixtureItem,
      logicalFixtureCount: number,
      hasOutput: boolean,
      outputEditable: boolean,
    ): readonly DebugWorkbenchEntry[] {
      const entries: DebugWorkbenchEntry[] = fixture.component.debugPanels
        .filter(panel => resolveDebugPanelPlacement(panel.placement, logicalFixtureCount) === 'canvas-right')
        .map(panel => ({
          key: `${fixture.id}:${panel.id}`,
          fixtureId: fixture.id,
          fixtureName: fixture.name,
          panelId: panel.id,
          title: panel.title,
          definition: panel,
        }));
      if (hasOutput && logicalFixtureCount === 1) {
        entries.push({
          key: `${fixture.id}:${OUTPUT_DEBUG_PANEL_ID}`,
          fixtureId: fixture.id,
          fixtureName: fixture.name,
          panelId: OUTPUT_DEBUG_PANEL_ID,
          title: 'Output',
          outputEditable,
        });
      }
      return entries;
    }

    function renderToolbarInputControls(
      reader: IReader,
      model: FixturePreviewItemModel,
    ): React.ReactNode {
      const controls = model.fixture.component.inputControls;
      const schemaProperties = model.fixture.component.inputSchema?.properties;
      const store = model.inputStore;
      if (!controls || !schemaProperties || !store) return null;

      return Object.entries(controls).flatMap(([name, options]) => {
        if (options.placement !== 'toolbar' && options.placement !== 'both') return [];
        const schema = schemaProperties[name];
        if (!schema) return [];
        const value = store.readValue(reader, name, schema);
        const label = options.label ?? name;
        if (schema.type === 'boolean') {
          return [(
            <button
              key={name}
              type="button"
              aria-pressed={value === true}
              title={options.title ?? label}
              style={{
                ...previewItemStyles.inputToggle,
                ...(value === true ? previewItemStyles.inputToggleActive : {}),
              }}
              onClick={() => store.setValue(name, schema, value !== true)}
            >
              {label}
            </button>
          )];
        }
        if (schema.enum && schema.enum.length > 0) {
          return [(
            <label key={name} style={previewItemStyles.inputSelectLabel} title={options.title}>
              <span>{label}</span>
              <select
                aria-label={label}
                style={previewItemStyles.modeSelect}
                value={String(value ?? '')}
                onChange={event => {
                  const next = schema.enum!.find(option => String(option) === event.target.value);
                  store.setValue(name, schema, next);
                }}
              >
                {schema.enum.map(option => (
                  <option key={String(option)} value={String(option)}>{String(option)}</option>
                ))}
              </select>
            </label>
          )];
        }
        return [];
      });
    }

  }
);

function PageViewportControls({
  fixtureId,
  pageMode,
  settings,
  geometry,
  store,
}: {
  readonly fixtureId: string;
  readonly pageMode: Extract<FixtureItem['component']['displayMode'], { type: 'page' }>;
  readonly settings: PageViewportSettings;
  readonly geometry: PagePreviewGeometry;
  readonly store: FixtureViewportStore;
}): React.ReactElement {
  const selectedViewport = resolveViewport(pageMode.viewports[settings.viewportIndex] ?? 'desktop');
  const usesSelectedViewport = settings.width === selectedViewport.width
    && settings.height === selectedViewport.height;
  const selectedValue = usesSelectedViewport ? String(settings.viewportIndex) : 'custom';

  return (
    <div style={previewItemStyles.viewportControls}>
      <select
        aria-label="Viewport preset"
        title="Viewport preset"
        style={previewItemStyles.viewportSelect}
        value={selectedValue}
        onChange={(event) => {
          if (event.target.value !== 'custom') {
            store.selectViewport(fixtureId, pageMode, Number(event.target.value));
          }
        }}
      >
        {pageMode.viewports.map((viewport, index) => (
          <option key={`${resolveViewport(viewport).name}-${index}`} value={String(index)}>
            {resolveViewport(viewport).name}
          </option>
        ))}
        {!usesSelectedViewport && <option value="custom">Custom</option>}
      </select>
      <DimensionInput
        label="Viewport width"
        value={settings.mode === 'responsive' ? geometry.logicalWidth : settings.width}
        disabled={settings.mode === 'responsive'}
        onCommit={(value) => store.setWidth(fixtureId, pageMode, value)}
      />
      <span style={previewItemStyles.dimensionSeparator}>×</span>
      <DimensionInput
        label="Viewport height"
        value={settings.mode === 'responsive' ? geometry.logicalHeight : settings.height}
        disabled={settings.mode === 'responsive'}
        onCommit={(value) => store.setHeight(fixtureId, pageMode, value)}
      />
      <select
        aria-label="Preview sizing mode"
        title="Preview sizing mode"
        style={previewItemStyles.modeSelect}
        value={settings.mode}
        onChange={(event) => store.setMode(fixtureId, pageMode, event.target.value as PagePreviewMode)}
      >
        <option value="fit">Fit</option>
        <option value="responsive">Responsive</option>
        <option value="actual">1:1</option>
      </select>
      {settings.mode === 'fit' && geometry.scale < 1 && (
        <span style={previewItemStyles.scaleText}>{Math.round(geometry.scale * 100)}%</span>
      )}
    </div>
  );
}

function DimensionInput({
  label,
  value,
  disabled = false,
  onCommit,
}: {
  readonly label: string;
  readonly value: number;
  readonly disabled?: boolean;
  readonly onCommit: (value: number) => void;
}): React.ReactElement {
  const commit = (target: HTMLInputElement): void => {
    const parsed = Number(target.value);
    if (Number.isFinite(parsed)) {
      onCommit(parsed);
    } else {
      target.value = String(value);
    }
  };

  return (
    <input
      key={`${label}-${value}`}
      aria-label={label}
      title={disabled ? `${label} follows available preview width` : label}
      type="number"
      min={1}
      max={10_000}
      defaultValue={String(value)}
      disabled={disabled}
      style={previewItemStyles.dimensionInput}
      onBlur={(event) => commit(event.currentTarget)}
      onKeyDown={(event) => {
        if (event.key === 'Enter') {
          event.currentTarget.blur();
        }
      }}
    />
  );
}

// Checkered pattern for transparency background (Figma-style)
const CHECKER_SIZE = 8;

function createCheckerPattern(baseColor: string, checkerColor: string): string {
  return `
    linear-gradient(45deg, ${checkerColor} 25%, transparent 25%),
    linear-gradient(-45deg, ${checkerColor} 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, ${checkerColor} 75%),
    linear-gradient(-45deg, transparent 75%, ${checkerColor} 75%)
  `;
}

const lightPattern = {
  backgroundColor: '#ffffff',
  backgroundImage: createCheckerPattern('#ffffff', '#e5e5e5'),
};

const darkPattern = {
  backgroundColor: '#1e1e1e',
  backgroundImage: createCheckerPattern('#1e1e1e', '#2d2d2d'),
};

const canvasBaseStyle: React.CSSProperties = {
  display: 'inline-block',
  padding: '12px',
  borderRadius: '4px',
  backgroundSize: `${CHECKER_SIZE * 2}px ${CHECKER_SIZE * 2}px`,
  backgroundPosition: `0 0, 0 ${CHECKER_SIZE}px, ${CHECKER_SIZE}px -${CHECKER_SIZE}px, -${CHECKER_SIZE}px 0`,
  boxShadow: '0 1px 3px rgba(0,0,0,0.12), 0 1px 2px rgba(0,0,0,0.08)',
  overflow: 'hidden',
  position: 'relative',
};

function getCanvasStyle(
  background: 'light' | 'dark',
  pageMode: PagePreviewMode | undefined,
): React.CSSProperties {
  const pattern = background === 'dark' ? darkPattern : lightPattern;
  return {
    ...canvasBaseStyle,
    ...(pageMode ? {
      display: 'block',
      width: '100%',
      boxSizing: 'border-box',
      overflow: pageMode === 'actual' ? 'auto' : 'hidden',
    } : {}),
    backgroundColor: pattern.backgroundColor,
    backgroundImage: pattern.backgroundImage,
  };
}

function getPageFrameStyle(
  geometry: PagePreviewGeometry,
  mode: PagePreviewMode,
): React.CSSProperties {
  return {
    position: 'relative',
    width: mode === 'responsive' ? '100%' : `${geometry.visualWidth}px`,
    height: `${geometry.visualHeight}px`,
    overflow: 'hidden',
  };
}

function getPageScaleLayerStyle(
  geometry: PagePreviewGeometry,
  mode: PagePreviewMode,
): React.CSSProperties {
  return {
    width: mode === 'responsive' ? '100%' : `${geometry.logicalWidth}px`,
    height: `${geometry.logicalHeight}px`,
    transform: geometry.scale === 1 ? undefined : `scale(${geometry.scale})`,
    transformOrigin: 'top left',
  };
}

function getDebugContentStyle(
  debugPaneOpen: boolean,
  fixtureColumnWidth: number | undefined,
  debugPaneWidth: number,
): React.CSSProperties {
  const fixtureTrack = fixtureColumnWidth === undefined
    ? 'minmax(0, 1fr)'
    : `${fixtureColumnWidth}px`;
  return {
    display: 'grid',
    alignItems: 'start',
    gridTemplateColumns: `${fixtureTrack} ${debugPaneOpen ? '8px' : '0px'} ${debugPaneOpen ? `${Math.max(0, debugPaneWidth)}px` : '0px'}`,
    width: '100%',
    minWidth: 0,
  };
}

function getLabelRowStyle(
  hasDebugEntries: boolean,
  debugPaneOpen: boolean,
  fixtureColumnWidth: number | undefined,
  contentHostWidth: number,
): React.CSSProperties {
  const width = !hasDebugEntries
    ? '100%'
    : debugPaneOpen
      ? contentHostWidth > 0 ? `${contentHostWidth}px` : '100%'
      : fixtureColumnWidth === undefined ? '100%' : `${fixtureColumnWidth}px`;
  return {
    ...previewItemStyles.labelRow,
    width,
    maxWidth: '100%',
  };
}

