function FixtureError({ error }: { error: ExceptionError }): React.ReactElement {
  const [expanded, setExpanded] = React.useState(false);

  return (
    <div style={errorStyles.container}>
      <button
        style={errorStyles.header}
        onClick={() => setExpanded(!expanded)}
      >
        <span style={errorStyles.chevron}>{expanded ? '▼' : '▶'}</span>
        <span style={errorStyles.message}>{error.message}</span>
      </button>
      {expanded && error.stack && (
        <pre style={errorStyles.stack}>{error.stack}</pre>
      )}
    </div>
  );
}

